-- 科室目录(31)
INSERT ALL
  INTO departments (dept_key, name, dept_group, intro) VALUES ('fever', '感染科门诊 / 发热门诊', '内科', '诊治发热查因、呼吸道/肠道等感染性疾病及肝炎等肝病；本部设独立 24 小时发热门诊，成人与儿童均可前往。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('resp', '呼吸与危重症医学科门诊', '内科', '诊治感冒、肺炎、支气管炎、哮喘、慢阻肺等呼吸系统疾病。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('cardio', '心血管内科门诊', '内科', '诊治高血压、冠心病、心律失常、心衰等心血管疾病，设有房颤、晕厥、心衰等专病门诊。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('neuro', '神经内科门诊', '内科', '诊治头痛、眩晕、脑血管病、癫痫、睡眠障碍等；设有眩晕门诊、头痛门诊、记忆门诊、中风筛查随访门诊。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('digest', '消化内科门诊', '内科', '诊治胃食管反流、胃炎、消化性溃疡、肠炎、肝炎等消化系统疾病，可开消化内镜（胃镜/肠镜）检查。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('endo', '内分泌科门诊', '内科', '诊治糖尿病、甲状腺疾病、骨质疏松、痛风、血脂紊乱等内分泌代谢疾病。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('nephro', '肾内科门诊', '内科', '诊治肾炎、肾病综合征、肾功能不全、血尿蛋白尿等肾脏疾病，设血透门诊。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('hemato', '血液内科门诊', '内科', '诊治贫血、白细胞/血小板异常、淋巴瘤、白血病等血液系统疾病。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('rheum', '风湿免疫科门诊', '内科', '诊治类风湿关节炎、痛风、系统性红斑狼疮、干燥综合征等风湿免疫疾病。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('psych', '心身医学中心 / 四川省精神医学中心', '内科', '诊治焦虑、抑郁、失眠等情绪与心身疾病；部分病区位于温江院区，就诊前请以医院导诊信息为准。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('general', '全科医疗科门诊', '内科', '适合初诊判断不明、多种慢病共存、体检异常随访、单纯开药复诊的人群，相当于“分诊中转站”。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('tumor', '肿瘤中心', '内科', '肿瘤的规范化内科/放疗综合诊治；发现明确肿瘤或占位后通常由专科转诊而来。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('ortho', '骨科门诊', '外科', '诊治颈肩腰腿痛、骨关节炎、骨折外伤、运动损伤等；急危重症骨科损伤走急诊。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('giSurg', '胃肠外科门诊', '外科', '诊治需外科处理的胃肠疾病：阑尾炎、肠梗阻、疝气、结直肠肿瘤、便血查因等。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('hbSurg', '肝胆胰外科门诊', '外科', '诊治肝胆胰脾外科疾病：胆囊结石、胆管结石、肝囊肿、胰腺及肝胆肿瘤等。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('thyroid', '甲状腺外科门诊', '外科', '诊治甲状腺结节、甲状腺肿瘤、颈部淋巴结等需外科评估的甲状腺疾病。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('uro', '泌尿外科门诊', '外科', '诊治泌尿系结石、前列腺疾病、膀胱肿瘤、排尿异常等；与肾内科共同处理血尿查因。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('breast', '乳腺外科 / 乳腺专病中心', '外科', '诊治乳腺结节、乳腺增生、乳腺癌筛查与治疗等乳腺疾病。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('vasc', '血管外科门诊', '外科', '诊治静脉曲张、深静脉血栓、动脉硬化闭塞、动脉瘤等血管疾病。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('nsurg', '神经外科门诊', '外科', '诊治颅脑外伤、脑肿瘤、脑血管畸形等需要外科处理的神经系统疾病。')
SELECT 1 FROM DUAL;

INSERT ALL
  INTO departments (dept_key, name, dept_group, intro) VALUES ('pedSurg', '小儿外科门诊', '外科', '14 岁以下儿童的外科疾病：疝气、鞘膜积液、包茎、外伤、先天畸形等。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('gyn', '妇科门诊', '妇产儿科', '诊治月经不调、异常阴道出血、白带异常、盆腔炎、子宫肌瘤、痛经等妇科疾病。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('ob', '产科门诊', '妇产儿科', '早孕建档、孕期产检、孕期不适评估、分娩咨询等；设早孕门诊、产前诊断门诊。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('pedi', '儿科门诊', '妇产儿科', '14 岁以下儿童的内科疾病：发热、咳嗽、腹泻、哮喘、发育评估等；儿童急症走急诊儿科通道。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('oph', '眼科门诊', '五官口腔皮肤', '诊治视力下降、眼红眼痛、干眼、近视斜弱视、白内障、青光眼等眼病，设干眼与近视防控门诊。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('ent', '耳鼻喉头颈外科门诊', '五官口腔皮肤', '诊治耳痛耳鸣、听力下降、鼻塞鼻炎、咽喉痛、眩晕（耳石症）等；头颈肿瘤亦归本中心。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('oral', '口腔医学中心（口腔全科）', '五官口腔皮肤', '诊治牙痛、龋齿、牙龈出血、口腔溃疡、牙齿矫正种植等；设口腔全科门诊与各专科门诊。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('derm', '皮肤科（皮肤病性病研究所）', '五官口腔皮肤', '诊治皮疹、荨麻疹、湿疹、痤疮、脱发、皮肤瘙痒、性病等皮肤病。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('emerg', '急诊医学科（急救中心）', '急诊与中心', '24 小时接诊急危重症：急性胸痛、卒中征兆、呼吸困难、大出血、意识障碍、严重外伤等；胸痛中心、卒中中心均设于此。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('rehab', '康复医学科（川港康复中心）', '急诊与中心', '针对颈肩腰腿痛、骨折术后、脑卒中后遗症的康复评估与治疗，多为其他科室转诊后介入。')
  INTO departments (dept_key, name, dept_group, intro) VALUES ('pain', '疼痛科门诊', '急诊与中心', '诊治长期难治性疼痛：慢性头痛、带状疱疹后神经痛、顽固性颈肩腰腿痛等。')
