-- 症状导诊条目(105)
INSERT ALL
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('fever', '发热', '发热与感染', '通用', 'fever', '感染科门诊（发热门诊）', '本部设独立 24 小时发热门诊（近急救中心，成人与儿童均可），夜间发热可直接前往。', 'yellow', '["上呼吸道感染","流行性感冒","急性咽炎","泌尿道感染（待排查）"]', '["呼吸与危重症医学科门诊","儿科门诊（≤14 岁）","急诊医学科（急症）"]', '["成人发热先居家测体温、多饮水；38.5℃ 以上可按说明使用退热药。","发热超过 3 天未退，或伴寒战、皮疹、关节痛、尿痛，建议到感染科查明原因。","普通感冒样发热可在呼吸内科/全科就诊；14 岁以下儿童挂儿科门诊。"]', '发热指体温超过 37.3℃，多数由病毒或细菌感染引起，如感冒、流感、咽炎等；体温 37.3–38℃ 属低热。发热本身是身体的防御反应，关键要找病因。', '体温 ≥39.5℃、高热抽搐、精神萎靡、呼吸急促、身上出现出血点/瘀斑，请立即到急诊医学科或发热门诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('fever-child', '儿童发热', '发热与感染', '儿童（≤14 岁）', 'pedi', '儿科门诊', '14 岁以下儿童发热原则上挂儿科；本部发热门诊也标注可接诊成人与儿童。', 'yellow', '["幼儿急疹","上呼吸道感染","流行性感冒","急性扁桃体炎（待排查）"]', '["发热门诊（夜间）","急诊医学科（急症）"]', '["先正确测量体温，观察精神状态比体温数字更重要：能吃能玩可先居家护理。","按体重给儿童退热药（对乙酰氨基酚/布洛芬二选一），切忌两种混用或成人药减量。","热性惊厥多见于 6 个月–5 岁儿童，多数短暂且不遗留损害，但首次发作应就医评估。"]', '儿童体温调节中枢发育不成熟，发热更常见于呼吸道或消化道感染。3 个月以下婴儿发热需格外警惕；幼儿急疹常表现为高热后出疹。', '3 个月以下婴儿发热、高热抽搐不止、精神萎靡叫不醒、呼吸急促、拒食伴脱水，立即去儿科急诊/急诊医学科。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('cough', '咳嗽', '呼吸系统', '通用', 'resp', '呼吸与危重症医学科门诊', '', 'green', '["急性支气管炎","上呼吸道感染","咳嗽变异性哮喘","肺炎（待排查）"]', '["感染科门诊","全科医疗科门诊","儿科门诊（≤14 岁）"]', '["感冒后咳嗽少于 2 周且无其他不适，可先观察、多喝水，避免自行滥用抗生素。","咳嗽超过 2 周、夜间或凌晨明显、遇冷/运动加重，建议就医排查咳嗽变异性哮喘等。","就诊时医生可能安排胸片、肺功能或过敏原检查。"]', '咳嗽是呼吸道的防御反射，可因感染、过敏、冷空气或胃食管反流刺激引起。急性咳嗽多与感冒相关，超过 3 周为慢性咳嗽，需查明病因。', '剧烈咳嗽伴明显呼吸困难、口唇发紫，或咳出大量鲜血，立即到急诊医学科。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('hemoptysis', '咯血 / 痰中带血', '呼吸系统', '成人', 'resp', '呼吸与危重症医学科门诊', '少量痰中带血丝可看门诊；血量较多或反复发作请直接急诊。', 'yellow', '["支气管扩张","肺结核","肺部肿瘤（待排查）","急性支气管炎"]', '["急诊医学科（出血量大时）","感染科门诊（疑结核）"]', '["少量血丝先别慌，记录出血量与次数，就医时告诉医生。","建议做胸部影像学检查（胸片/CT），必要时支气管镜检查。"]', '痰中带血提示呼吸道黏膜或肺实质出血，常见于感染、支气管扩张；反复或较多咯血需警惕结核、肿瘤等，务必查明来源。', '大口咯血、咯血不止伴胸闷窒息感，立即急诊，保持侧卧防止误吸。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('dyspnea', '喘息 / 呼吸困难', '呼吸系统', '通用', 'resp', '呼吸与危重症医学科门诊', '哮喘急性发作或突发严重气促，不要等门诊，直接去急诊。', 'yellow', '["支气管哮喘","慢性阻塞性肺疾病","肺炎","心功能不全（待排查）"]', '["心血管内科门诊（排查心源性）","急诊医学科（急症）","儿科门诊（≤14 岁）"]', '["已知哮喘者请随身携带急救吸入剂，记录发作频率和诱因。","慢阻肺/哮喘需要长期规范用药与肺功能随访，勿自行停药。","新发活动后气短需同时排查心脏原因。"]', '呼吸困难是重要的警示信号，可由气道（哮喘、慢阻肺）、肺组织（肺炎）或心脏（心衰）问题引起。反复发作的喘息多见于哮喘或慢阻肺。', '静息状态下仍气促、说话不成句、口唇指甲发紫、端坐呼吸，立即拨打 120 或到急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('chestpain', '胸痛 / 胸闷', '心脑血管', '成人', 'cardio', '心血管内科门诊', '症状不重、短暂发作可先看心内科；典型心绞痛发作请走急诊胸痛中心。', 'red', '["心绞痛","急性冠脉综合征（待排查）","肋间神经痛","胃食管反流","胸膜炎"]', '["急诊医学科（胸痛中心）","呼吸与危重症医学科门诊","消化内科门诊"]', '["发作时先停止活动、静坐休息，舌下含服硝酸甘油（既往医嘱可用时）。","记录胸痛与活动、进食、呼吸的关系，有助于鉴别病因。","中年以上伴高血压、糖尿病、吸烟者，胸痛务必优先排除心脏问题。"]', '胸痛病因可从心脏（心绞痛/心梗）、肺、食管到肌肉骨骼，性质差别很大。心源性胸痛通常为压榨、闷痛，活动后加重、休息缓解，是中老年高危信号。', '压榨样胸痛持续超 15 分钟、向左侧肩背放射、伴大汗/恶心/濒死感，立即拨打 120——急性心梗救治争分夺秒。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('palpitation', '心慌 / 心悸', '心脑血管', '通用', 'cardio', '心血管内科门诊', '', 'green', '["心律失常（早搏/心动过速）","甲状腺功能亢进","贫血","焦虑状态（待排查）"]', '["内分泌科门诊（查甲功）","血液内科门诊（查贫血）","心身医学中心"]', '["发作时数一下脉率、是否规律，最好记录下来给医生看。","医生可能安排心电图、24 小时动态心电图、甲功和血常规。","先减少咖啡浓茶与熬夜观察；仍频繁发作再就医。"]', '心悸是自觉心跳过快、过乱或漏跳。偶发可因熬夜、咖啡、紧张；频繁发作或伴头晕则可能为心律失常，也可能源于甲亢、贫血等。', '心跳极快伴眼前发黑、晕厥、胸痛，或脉搏明显不齐伴气促，立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('stroke', '中风征兆（口角歪斜 / 单侧无力 / 言语不清）', '心脑血管', '中老年高发', 'emerg', '急诊医学科（卒中中心）', '「FAST」快速识别：Face 面部歪斜、Arm 单侧无力、Speech 言语不清、Time 立即就医。', 'red', '["急性缺血性脑卒中","脑出血（待排查）","面神经炎（需鉴别）"]', '["神经内科门诊（恢复期/后续诊治）"]', '["让患者立即平卧、头偏向一侧，不要喂水喂药（可能呛咳误吸）。","记录症状开始的准确时间，这是医生选择治疗方案的关键。","发病 24 小时内即使症状缓解（小中风/TIA）也应就医评估。"]', '脑卒中分缺血性（血管堵塞）和出血性（血管破裂）。缺血性卒中黄金救治时间窗约 4.5 小时，越早溶栓/取栓，致残率越低，务必分秒必争。', '突然口角歪斜、一侧肢体无力、言语不清、视物重影或突发的剧烈头痛——任何一项都立即拨打 120，切勿自驾。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('syncope', '晕厥 / 意识不清', '心脑血管', '通用', 'emerg', '急诊医学科', '晕厥病因需心内科与神经内科联合排查，急性期先急诊处理。', 'red', '["心源性晕厥","体位性低血压","低血糖","癫痫发作（待排查）"]', '["心血管内科门诊（晕厥门诊）","神经内科门诊"]', '["目击者让患者平卧、抬高下肢，保持气道通畅，不要掐人中延误送医。","就医前回忆晕厥前诱因：是否久站、情绪激动、饥饿或用力后发生。","既往有心律失常、晕厥史者遵医嘱复查动态心电图。"]', '晕厥是大脑一过性缺血导致的短暂意识丧失。原因可从良性（体位性低血压）到致命（恶性心律失常），反复晕厥必须系统检查。', '意识丧失超过数分钟不醒、伴抽搐或呼吸异常、跌倒致头部外伤，立即拨打 120。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('headache', '头痛', '神经系统', '通用', 'neuro', '神经内科门诊', '医院设有头痛专病门诊；伴鼻塞流脓涕的头痛也可能先看耳鼻喉科。', 'green', '["紧张型头痛","偏头痛","高血压头痛","鼻窦炎性头痛（待排查）"]', '["全科医疗科门诊","耳鼻喉头颈外科门诊","疼痛科门诊（慢性）"]', '["记录头痛频率、部位、诱因（睡眠、压力、食物）和缓解方式，就诊时很有帮助。","自行长期服用止痛药可能造成药物过度使用性头痛，勿过量。","伴鼻塞、面部胀痛的头痛可考虑鼻源性头痛。"]', '头痛很常见，多数为紧张型或偏头痛等原发性头痛。但如果头痛性质突然改变、进行性加重，或伴有神经系统症状，就要警惕继发性病因。', '突发「一生中最剧烈」的头痛（雷击样）、伴喷射性呕吐、肢体无力或视物模糊，立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('vertigo', '头晕 / 眩晕', '神经系统', '通用', 'neuro', '神经内科门诊（眩晕门诊）', '医院神经内科设有眩晕专病门诊；与体位改变相关的短暂眩晕也常由耳石症引起，耳鼻喉头颈外科可复位治疗。', 'green', '["良性阵发性位置性眩晕（耳石症）","梅尼埃病","前庭神经炎","脑供血不足（待排查）"]', '["耳鼻喉头颈外科门诊","心血管内科门诊（晕厥门诊）","全科医疗科门诊"]', '["眩晕发作时扶稳防跌倒，闭眼静卧多可缓解。","医生常用位置诱发试验（如 Dix-Hallpike）来判断耳石症。","反复眩晕伴耳鸣耳闷者，梅尼埃病可能，需控制盐摄入并随访。"]', '眩晕（天旋地转）多与内耳前庭或脑干小脑病变有关；头昏（昏沉感）多与血压、颈椎、疲劳有关。耳石症是最常见的一种眩晕，翻身/抬头时短暂发作。', '眩晕伴口齿不清、肢体无力、复视、行走明显不稳（急性脑血管病可能），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('insomnia', '失眠 / 睡眠障碍', '神经系统', '成人', 'neuro', '神经内科门诊', '医院神经内科诊治睡眠障碍；若失眠与情绪压力明显相关，也可看心身医学中心。', 'green', '["失眠症","焦虑抑郁伴发失眠","睡眠呼吸暂停（打鼾憋气）","不宁腿综合征（待排查）"]', '["心身医学中心 / 四川省精神医学中心","全科医疗科门诊"]', '["先做睡眠卫生调整：固定作息、睡前不用手机、午后不喝咖啡。","打鼾明显伴白天嗜睡者，建议做睡眠监测排查呼吸暂停。","安眠药请遵医嘱短期使用，不要自行长期服用或突然停药。"]', '失眠指入睡困难、易醒或早醒并影响白天状态，持续 3 个月以上为慢性失眠。情绪压力、作息紊乱是最常见诱因，部分患者与呼吸暂停（打鼾憋气）有关。', '失眠伴严重情绪低落、有自伤或自杀念头，请立即寻求心理危机干预或急诊帮助。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('numbness', '肢体麻木 / 无力', '神经系统', '成人', 'neuro', '神经内科门诊', '', 'yellow', '["颈椎病/腰椎病（神经根受压）","周围神经病","糖尿病周围神经病变","脑血管病（待排查）"]', '["骨科门诊（颈腰椎病变）","内分泌科门诊（糖尿病神经病变）","急诊医学科（突发单侧无力）"]', '["区分「哪只手麻、什么姿势麻」：低头/提重物诱发多与颈椎相关。","糖尿病人群出现袜套样手脚麻木，提示周围神经病变可能。","建议做肌电图、颈椎/腰椎影像等检查定位病因。"]', '麻木无力需区分是中枢性（大脑/脊髓）还是周围性（神经根、周围神经）。突发单侧肢体无力是中风的典型信号；慢性麻木则常与颈椎腰椎、糖尿病相关。', '单侧肢体突然无力伴口角歪斜、言语不清，立即按中风处理拨打 120。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('seizure', '抽搐 / 惊厥', '神经系统', '通用', 'neuro', '神经内科门诊', '发作期或频繁发作请走急诊；缓解期看神经内科（设癫痫专病方向）。', 'yellow', '["癫痫","高热惊厥（儿童）","电解质紊乱","脑部病变（待排查）"]', '["急诊医学科（发作期）","儿科门诊（儿童热性惊厥）"]', '["发作时保护头部、移开周围硬物，让患者侧卧，不要往嘴里塞东西或按压肢体。","记录发作时间与表现（哪侧先动、持续多久），对诊断很有用。","确诊癫痫者规律服药，勿自行停药，避免熬夜饮酒等诱因。"]', '抽搐是大脑异常放电或代谢异常引起。儿童常见高热惊厥（6 个月–5 岁），成人反复抽搐多为癫痫，需脑电图等系统评估。', '抽搐持续超过 5 分钟、反复发作意识不恢复、发作后持续昏迷，立即拨打 120。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('abdominal-pain', '腹痛 / 肚子疼', '消化系统', '通用', 'digest', '消化内科门诊', '急性剧烈腹痛、持续不缓解请直接急诊，勿自行服用止痛药掩盖病情。', 'yellow', '["急性胃肠炎","胃十二指肠溃疡","胆囊炎/胆结石","阑尾炎（需排查）","肠易激综合征"]', '["胃肠外科门诊","急诊医学科（急腹症）","妇科门诊（女性下腹痛）","儿科门诊（≤14 岁）"]', '["就医前注意疼痛位置、性质、是否转移（如从肚脐周转移到右下腹），医生最关心这些。","暂时禁食观察，明确前避免热敷掩盖症状；怀疑急腹症时不要服止痛药。","反复发作的腹痛可查胃镜、腹部超声等。"]', '腹痛病因复杂：上腹痛多与胃、胆囊相关；右下腹痛需警惕阑尾炎；女性下腹痛要考虑妇科。阵发痉挛性疼痛伴腹泻多为急性胃肠炎。', '剧烈持续腹痛、按压更痛、腹肌发硬、伴发热寒战或呕血便血，立即急诊——可能是急腹症（阑尾炎、穿孔、宫外孕等）。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('diarrhea', '腹泻', '消化系统', '通用', 'digest', '消化内科门诊', '', 'green', '["急性肠炎","细菌性痢疾（脓血便）","肠易激综合征","炎症性肠病（慢性，待排查）"]', '["感染科门诊（疑肠道感染）","儿科门诊（≤14 岁）","全科医疗科门诊"]', '["首选口服补液盐防脱水；清淡饮食，避免牛奶、油腻与生冷。","成人轻症可先用蒙脱石散与益生菌；发烧超过 38.5℃ 或脓血便尽早就医。","反复腹泻超 4 周、伴体重下降或夜间腹泻，需排查炎症性肠病等。"]', '腹泻多为进食不洁或受凉引起的肠道感染，通常 3–5 天自愈。补水是第一位；脓血便提示细菌性感染可能需抗菌治疗。', '婴幼儿或老年人腹泻伴精神差、眼窝凹陷、尿量明显减少（脱水），或高热不退、脓血便，立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('constipation', '便秘', '消化系统', '通用', 'digest', '消化内科门诊', '', 'green', '["功能性便秘","肠易激综合征（便秘型）","盆底功能障碍","结直肠病变（待排查）"]', '["胃肠外科门诊（顽固性便秘）","全科医疗科门诊"]', '["增加膳食纤维（蔬菜、粗粮、火龙果等）与饮水，固定时间如厕。","泻药（含刺激性成分）不宜长期依赖，应在医生指导下逐步调整。","排便习惯近期明显改变或伴便血、消瘦者，建议做肠镜排查。"]', '便秘指每周排便少于 3 次或排便费力、粪便干硬。多数与膳食纤维不足、饮水少、缺乏运动及久坐有关，改变生活方式是基础。', '腹痛腹胀剧烈、停止排气排便（肠梗阻可能）或呕粪样物，立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('gerd', '反酸 / 烧心', '消化系统', '成人', 'digest', '消化内科门诊', '需要做胃镜评估可挂消化内科门诊后开消化内镜（胃镜）检查。', 'green', '["胃食管反流病","慢性胃炎","食管炎","功能性消化不良（待排查）"]', '["全科医疗科门诊"]', '["睡前 3 小时不进食，饭后不立即平躺，少咖啡、浓茶、酒精与甜食。","睡觉可抬高床头 15–20cm；超重者减重可明显改善。","症状频繁（每周 ≥2 次）建议就医规范用药（抑酸药），勿长期自行购药。"]', '反酸烧心是胃内容物反流到食管引起，躺下或弯腰时加重。长期反流可损伤食管黏膜，甚至引发反流性食管炎、Barrett 食管。', '伴吞咽困难、吞咽痛、消瘦、黑便，或胸痛剧烈难以与心绞痛鉴别时，尽快就医。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('nausea', '恶心 / 呕吐', '消化系统', '通用', 'digest', '消化内科门诊', '育龄女性晨起恶心先排除怀孕，可看妇科/产科。', 'green', '["急性胃炎","胃肠型感冒","眩晕所致呕吐","早孕反应（育龄女性，待排查）"]', '["全科医疗科门诊","妇科门诊（早孕）","神经内科门诊（眩晕呕吐）"]', '["少量多次补水，先清淡流质（米汤）再逐步过渡；不要勉强进食。","呕吐频繁可临时使用止吐药，但持续呕吐或伴其他症状需就医。","记录是否与进食、用药、乘车、月经周期相关。"]', '恶心呕吐是胃肠刺激、药物、前庭眩晕或早孕等引起的反射。大多数急性呕吐可自行缓解，重点是防脱水与寻找诱因。', '呕血或呕吐物呈咖啡色、剧烈头痛伴喷射性呕吐、呕吐伴剧烈腹痛或意识改变，立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('hematochezia', '便血 / 黑便', '消化系统', '成人', 'digest', '消化内科门诊', '便鲜血且长期便秘者也可直接看胃肠外科评估痔与直肠病变。', 'yellow', '["痔疮/肛裂","结直肠息肉或肿瘤（待排查）","消化性溃疡出血","炎症性肠病"]', '["胃肠外科门诊","急诊医学科（大量出血）"]', '["不要因为「可能是痔疮」就忽视——中老年新发便血务必做肠镜排除肿瘤。","记录血的颜色、量与排便关系，就医时准确描述。","服用铁剂、铋剂或进食动物血会使大便变黑，先排除这类情况。"]', '便血要区分颜色与来源：鲜红色附着于大便表面多为肛门直肠出血（痔疮、肛裂）；黑便/柏油样便提示上消化道出血。无论哪种，反复出血都需肠镜/胃镜查明。', '大量便血伴头晕心慌、血压下降，或呕血与便血同时出现，立即急诊。')
SELECT 1 FROM DUAL;

INSERT ALL
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('jaundice', '黄疸（皮肤 / 眼白发黄）', '消化系统', '通用', 'fever', '感染科门诊（肝病门诊）', '医院感染科设有乙肝临床治愈及肝病专病门诊，可查肝功能与病毒标志物。', 'yellow', '["病毒性肝炎","胆道梗阻（结石/肿瘤）","酒精性或药物性肝损伤（待排查）"]', '["消化内科门诊","肝胆胰外科门诊（疑胆道梗阻）"]', '["就诊前不要自行服「退黄药」，先查肝功能、乙肝等病毒学指标。","如实告知饮酒史、用药史（含保健品）——很多肝损伤与药物相关。","伴右上腹痛、发热者高度怀疑胆道问题，需做腹部超声。"]', '黄疸是血液胆红素升高使皮肤、巩膜黄染，分肝细胞性（肝炎）、梗阻性（胆结石/肿瘤堵住胆道）与溶血性三类，必须查明是哪一种。', '黄疸伴高热寒战、剧烈腹痛（急性胆管炎可能）或意识改变（肝性脑病可能），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('diabetes-suspect', '多饮多尿 / 体重下降', '内分泌', '成人', 'endo', '内分泌科门诊', '', 'yellow', '["糖尿病","甲状腺功能亢进","尿崩症（待排查）"]', '["全科医疗科门诊（查空腹血糖）"]', '["就医前可先查一次空腹血糖和糖化血红蛋白，但不要自行诊断用药。","确诊糖尿病后重在生活方式干预 + 定期监测，避免并发症。","伴心慌手抖、怕热多汗、脾气急躁者同步查甲状腺功能。"]', '「多饮、多尿、多食、体重下降」是糖尿病典型信号，也可由甲亢等代谢亢进疾病引起。体检或症状提示血糖异常时应尽早规范检查。', '恶心呕吐、深大呼吸、呼气有烂苹果味（糖尿病酮症酸中毒可能），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('goiter', '颈部包块 / 甲状腺肿大', '内分泌', '成人', 'thyroid', '甲状腺外科门诊', '医院设甲状腺外科门诊并可做甲状腺介入超声；甲功异常的内科调整由内分泌科负责。', 'yellow', '["甲状腺结节","甲状腺肿","甲状腺肿瘤（待排查）","淋巴结肿大"]', '["内分泌科门诊（查甲功）","超声医学科（甲状腺超声）"]', '["先做甲状腺超声 + 甲功检查，明确结节大小、形态与功能状态。","良性结节通常每 6–12 个月复查即可，无需过度紧张。","结节短期内迅速增大、声音嘶哑加重、吞咽呼吸困难需尽快就诊。"]', '颈前区（喉结下方）包块多为甲状腺结节，体检发现率很高，绝大多数为良性。超声按 TI-RADS 分级评估风险，必要时穿刺活检。', '包块迅速增大伴明显呼吸困难或咯血，立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('edema', '水肿 / 泡沫尿', '肾脏', '成人', 'nephro', '肾内科门诊', '', 'yellow', '["肾小球肾炎","肾病综合征","心功能不全","甲状腺功能减退（待排查）"]', '["心血管内科门诊（下肢水肿伴活动后气促）","内分泌科门诊"]', '["晨起留取中段尿查尿常规，并测血压——肾病常伴高血压。","记录水肿是晨轻暮重（多与心/肾相关）还是活动后加重。","不要盲目吃「利尿消肿」的偏方，先明确病因。"]', '晨起眼睑肿、午后下肢肿、尿中泡沫久不消散，提示肾脏滤过功能或蛋白漏出异常可能；心衰与甲减也可引起水肿。尿常规是第一步检查。', '尿量骤减甚至无尿、伴喘憋不能平卧，或水肿伴血压急剧升高，立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('hematuria', '血尿', '肾脏', '通用', 'uro', '泌尿外科门诊', '伴尿痛的多为感染/结石先看泌尿外科；无痛肉眼血尿更要查因，勿拖延。', 'yellow', '["泌尿系感染","泌尿系结石","肾小球肾炎","泌尿系肿瘤（无痛血尿，待排查）"]', '["肾内科门诊（肾炎性血尿）","急诊医学科（大量血尿伴绞痛）"]', '["回忆诱因：剧烈运动、药物（如某些止痛药）、月经期污染都可造成假性血尿。","查尿常规 + 泌尿系超声是基础组合。","无痛肉眼血尿哪怕只有一次，也建议认真排查。"]', '血尿分肉眼血尿与镜下血尿。伴尿频尿痛多为感染或结石；无痛性肉眼血尿是中老年泌尿系肿瘤的重要警示，务必查超声与尿细胞学。', '大量血尿伴血块、剧烈绞痛或无法排尿（尿潴留），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('dysuria', '尿频 / 尿急 / 尿痛', '肾脏', '通用', 'uro', '泌尿外科门诊', '', 'green', '["泌尿系感染（膀胱炎/尿道炎）","前列腺增生","膀胱过度活动症（待排查）"]', '["肾内科门诊","妇科门诊（女性反复感染）","儿科门诊（儿童排尿异常）"]', '["多饮水、不憋尿；留中段尿查尿常规后再用药，避免经验性滥用抗生素。","反复发作（一年 ≥3 次）建议做泌尿系超声与残余尿评估。","糖尿病患者尿路感染更易发生，注意血糖控制。"]', '尿频尿急尿痛是泌尿系感染的典型表现，女性更多见；中老年男性夜尿多常与前列腺增生有关。规范抗菌治疗与足够疗程很关键。', '发热寒战伴腰痛（肾盂肾炎可能）、完全排不出尿（急性尿潴留），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('anemia', '贫血 / 乏力苍白', '血液', '通用', 'hemato', '血液内科门诊', '', 'yellow', '["缺铁性贫血","巨幼细胞性贫血","慢性病贫血","血液系统疾病（待排查）"]', '["全科医疗科门诊","消化内科门诊（排查消化道失血）","妇科门诊（月经过多）"]', '["查血常规 + 铁蛋白、叶酸、维生素 B12，判断贫血类型。","女性月经过多、大便隐血阳性者要同步找失血源头。","补铁请遵医嘱并复查，不要长期自行乱补。"]', '贫血是血红蛋白低于正常，表现为乏力、头晕、苍白。铁缺乏是最常见原因，可能与饮食、失血（月经过多/消化道出血）或吸收障碍有关。', '贫血伴发热、皮肤出血点瘀斑、淋巴结肿大（血液系统恶性疾病可能），尽快血液科就诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('lymphadenopathy', '淋巴结肿大', '血液', '通用', 'hemato', '血液内科门诊', '伴红肿热痛的炎性肿大也可先看全科或感染科；无痛性、进行性肿大多部位肿大建议血液科排查。', 'yellow', '["反应性增生（炎症）","淋巴结炎","淋巴瘤/转移瘤（无痛性肿大，待排查）"]', '["全科医疗科门诊","感染科门诊","肿瘤中心"]', '["先观察：直径 <1cm、活动好、有压痛、与感染相关的，多数是炎症反应。","肿大超过 2 周不消、无痛且持续增大，建议做超声并考虑活检。","伴发热、盗汗、半年内体重下降超过 10%，尽早就医。"]', '淋巴结是免疫器官，感染时会肿大伴压痛，炎症消退后多缩小。若出现无痛性、质地硬、进行性增大或全身多处肿大，需警惕淋巴瘤等。', '肿大淋巴结压迫气道致呼吸困难，或多处快速增大伴全身症状，尽快就诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('backpain', '腰痛', '骨科运动', '通用', 'ortho', '骨科门诊', '', 'green', '["腰肌劳损","腰椎间盘突出","腰椎退行性变","泌尿系结石（绞痛，需鉴别）"]', '["康复医学科（川港康复中心）","泌尿外科门诊（绞痛伴血尿）","肾内科门诊"]', '["急性期减少弯腰负重，可短期外用止痛药；48 小时后可热敷。","慢性腰痛重点在康复锻炼：核心肌群训练、避免久坐。","伴下肢放射痛、麻木者查腰椎 MRI 明确神经受压程度。"]', '腰痛绝大多数与肌肉韧带劳损、腰椎退变有关，急性腰扭伤多可 1–2 周缓解。反复发作或伴下肢放射痛提示神经受压。', '腰痛伴下肢麻木无力、大小便失禁（马尾综合征可能），或腰痛伴发热，立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('neckpain', '颈肩痛', '骨科运动', '通用', 'ortho', '骨科门诊', '', 'green', '["颈椎病","肩周炎（冻结肩）","颈部肌肉劳损","肩袖损伤（待排查）"]', '["疼痛科门诊（慢性疼痛）","康复医学科（川港康复中心）"]', '["纠正低头姿势：屏幕抬高、每 40 分钟起身活动。","颈椎锻炼（如米字操）以不加重疼痛为度，避免快速甩头。","手麻伴颈痛者查颈椎 MRI；肩痛抬举困难者查肩关节超声/磁共振。"]', '长期低头使颈椎与肩颈肌肉劳损，出现酸痛僵硬；颈椎间盘突出压迫神经可致上肢麻木。肩周炎表现为肩关节活动受限，夜间痛明显。', '颈部外伤后四肢麻木无力，或颈肩痛伴下肢踩棉花感、走路不稳，尽快急诊/骨科。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('trauma', '外伤 / 骨折', '骨科运动', '通用', 'ortho', '骨科门诊', '白天轻中度扭伤看骨科门诊；疑似骨折、大出血、头部外伤请直接急诊。', 'yellow', '["软组织挫伤","韧带损伤","骨折","关节脱位（需拍片明确）"]', '["急诊医学科（急症）","小儿外科门诊（儿童骨折）"]', '["扭伤后按 RICE 原则：休息、冰敷（24–48 小时内）、加压、抬高患肢。","疑似骨折先用夹板/硬纸板简单固定，避免移动加重损伤。","伤后 3 天仍明显肿痛或不敢负重，务必拍片复查。"]', '外伤按「红、肿、痛、功能障碍」判断：能负重、无明显畸形多为软组织伤；剧痛、变形、骨擦感或无法活动提示骨折可能，需拍 X 线明确。', '开放性骨折（骨头外露）、大出血不止、头部撞击后意识改变或喷射性呕吐，立即拨打 120。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('rash', '皮疹 / 荨麻疹', '皮肤科', '通用', 'derm', '皮肤科（皮肤病性病研究所）', '', 'green', '["荨麻疹","湿疹","过敏性皮炎","药疹（需排查）","病毒性皮疹"]', '["全科医疗科门诊","儿科门诊（≤14 岁）"]', '["回忆发病前 24 小时饮食、用药与接触物，找到并回避诱因。","可先用抗组胺药（如氯雷他定）缓解，但反复发作应就医规范治疗。","全身大片皮疹伴发热需排查感染性或药疹，不要自行涂激素软膏掩盖。"]', '荨麻疹表现为突发的红色风团、剧烈瘙痒，可因食物、药物、感染或冷热刺激诱发，多数 24 小时内消退；反复超过 6 周为慢性荨麻疹。', '皮疹伴口唇/喉头肿胀、呼吸困难、声音嘶哑（严重过敏反应），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('eczema', '湿疹 / 皮炎', '皮肤科', '通用', 'derm', '皮肤科（皮肤病性病研究所）', '', 'green', '["湿疹","特应性皮炎","接触性皮炎","真菌感染（需鉴别）"]', '["儿科门诊（儿童湿疹）"]', '["保湿是基础：洗澡后 3 分钟内涂保湿霜，坚持使用可明显减少复发。","避免搔抓、热水烫洗与碱性洗涤剂；瘙痒剧烈可口服抗组胺药。","外用药请遵医嘱分级使用，不要长期自行用强效激素。"]', '湿疹是皮肤屏障受损 + 免疫炎症导致的慢性瘙痒性皮肤病，与遗传、环境、刺激物有关。特点是反复发作、对称分布、皮肤干燥脱屑。', '皮疹突然大面积泛发、渗液伴发热（继发感染可能），尽快就诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('acne', '痤疮（青春痘）', '皮肤科', '青少年及青年', 'derm', '皮肤科（皮肤病性病研究所）', '医院皮肤科/医疗美容科可规范治疗痤疮及痘印。', 'green', '["寻常痤疮","囊肿性痤疮","玫瑰痤疮（需鉴别）"]', '[]', '["少熬夜、少高糖高脂饮食；温和清洁、不挤痘（易留疤留印）。","治疗需耐心：维 A 酸类、过氧化苯甲酰等外用 8–12 周起效。","重度痤疮请在皮肤科医生指导下系统用药，勿信偏方。"]', '痤疮与雄激素、皮脂分泌、毛囊角化及痤疮丙酸杆菌相关。轻度以粉刺为主，中重度可出现炎性丘疹、脓疱甚至囊肿结节。', '面部出现大片红肿热痛的囊肿结节或发热（严重感染可能），尽快就诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('alopecia', '脱发', '皮肤科', '通用', 'derm', '皮肤科（皮肤病性病研究所）', '', 'green', '["雄激素性脱发","斑秃","脂溢性皮炎","休止期脱发（待排查）"]', '[]', '["就医前观察脱发形态（发际线、头顶或成片），可拍照记录。","大手术后、产后、高烧后 2–3 个月出现弥漫脱发多为休止期脱发，可自行恢复。","雄激素性脱发需长期规范用药（如米诺地尔），越早干预效果越好。"]', '每天自然脱落 50–100 根属正常；若明显变稀或成片脱落需就医。雄激素性脱发最常见（前额发际线后退/头顶稀疏），斑秃表现为圆形脱发斑。', '短期内（数天）头发成片快速脱落或伴头皮红肿破溃，尽快皮肤科就诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('menstrual', '月经不调', '妇产', '女性（育龄期）', 'gyn', '妇科门诊', '', 'green', '["排卵障碍/多囊卵巢综合征","内分泌失调","子宫肌瘤/内膜病变","妊娠相关（需先排除）"]', '["生殖内分泌门诊","内分泌科门诊（甲功/泌乳素异常）"]', '["育龄女性月经推迟先验孕，排除妊娠再谈调经。","记录月经周期与经量，医生会根据情况安排性激素、妇科超声。","长期月经稀发伴肥胖、多毛者需排查多囊卵巢综合征。"]', '正常月经周期 21–35 天、经期 3–7 天。偶有一次推迟多与压力、熬夜、减重有关；连续 3 个周期异常或出血量明显改变，建议妇科系统检查。', '停经后突发剧烈下腹痛伴阴道出血（宫外孕破裂可能），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('gyne-discharge', '白带异常 / 外阴不适', '妇产', '女性', 'gyn', '妇科门诊', '', 'green', '["阴道炎（霉菌/细菌/滴虫）","宫颈炎","盆腔炎（伴腹痛）","宫颈病变（需筛查）"]', '["生殖医学中心（备孕相关）"]', '["就医前不要阴道冲洗或用药，以免影响白带化验结果。","常规做白带常规 + 妇科检查；有性生活者定期做宫颈 TCT/HPV 筛查。","遵医嘱足疗程用药，性伴侣同治（滴虫），避免反复感染。"]', '白带性状改变（颜色、气味、量）伴瘙痒多提示阴道炎：豆腐渣样多为霉菌，黄绿色泡沫样多为滴虫。同房后出血需重视宫颈筛查。', '白带异常伴高热、剧烈下腹痛（急性盆腔炎可能），尽快就诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('pregnancy', '早孕 / 备孕建档', '妇产', '女性', 'ob', '产科门诊（早孕门诊）', '医院设早孕门诊，早孕期建档、产检评估均可在此进行。', 'green', '["正常宫内妊娠","先兆流产（腹痛出血时）","宫外孕（需排除）"]', '["妇科门诊","急诊医学科（腹痛出血急症）"]', '["孕早期补充叶酸（0.4–0.8mg/日），避免烟酒与自行用药。","出现少量褐色分泌物先卧床观察并尽快就医评估。","按医生安排完成 NT、唐筛/无创 DNA、大排畸等重要检查。"]', '确认怀孕后应尽早到产科门诊建档，进行孕早期检查（血 HCG、孕酮、B 超）评估胚胎情况，并按计划完成产前筛查。', '孕早期剧烈下腹痛或阴道出血量多伴头晕（宫外孕或流产可能），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('child-cough', '儿童咳嗽 / 喘息', '儿科', '儿童（≤14 岁）', 'pedi', '儿科门诊', '', 'yellow', '["急性支气管炎","毛细支气管炎（婴幼儿）","儿童哮喘","支原体肺炎（待排查）"]', '["呼吸与危重症医学科门诊（儿童哮喘专科）","小儿外科门诊（呛咳异物）","急诊医学科（急症）"]', '["观察呼吸频率与精神：能安静玩耍、无口唇发紫可先门诊就诊。","夜间咳喘明显、运动后加重，就医时提醒医生评估哮喘可能。","雾化与用药请遵儿科剂量，不要拿成人药减量给儿童。"]', '儿童呼吸道感染高发，咳嗽是主要表现。婴幼儿气道窄，分泌物多时易喘；反复喘息要警惕儿童哮喘，支原体肺炎近年也不少见。', '呼吸急促（鼻翼扇动、三凹征）、口唇发紫、呛咳后突发剧烈咳嗽（异物可能），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('child-abdomen', '儿童腹痛 / 呕吐', '儿科', '儿童（≤14 岁）', 'pedi', '儿科门诊', '', 'yellow', '["急性胃肠炎","肠系膜淋巴结炎","肠套叠（阵发性哭闹，需警惕）","便秘（待排查）"]', '["小儿外科门诊（外科腹痛）","急诊医学科（急症）"]', '["观察哭闹模式：阵发性加重（一阵一阵）与持续哭闹意义不同。","呕吐腹泻者重点防脱水，少量多次喂口服补液盐。","3 岁以下宝宝腹痛不会表达，多表现为异常哭闹、蜷腿。"]', '儿童腹痛最常见是胃肠炎与肠系膜淋巴结炎。婴幼儿阵发性剧烈哭闹、呕吐、果酱样血便要高度警惕肠套叠，这是小儿外科急症。', '阵发性剧烈哭闹伴果酱样血便、频繁呕吐、腹部摸到包块（肠套叠可能），或剧痛持续伴发热，立即急诊。')
SELECT 1 FROM DUAL;

INSERT ALL
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('eye', '眼红 / 眼痛 / 视力下降', '五官科', '通用', 'oph', '眼科门诊', '', 'yellow', '["结膜炎（红眼病）","干眼症","角膜炎（眼痛畏光流泪）","青光眼/视网膜病变（视力骤降，待排查）"]', '["急诊医学科（眼部外伤）"]', '["结膜炎注意卫生，毛巾分开，勿揉眼交叉感染。","干眼症与用眼过度相关，可先热敷与人工泪液，持续不适再就医。","视力突然下降哪怕不痛也要当急症处理。"]', '眼红伴分泌物多为结膜炎（细菌性黄脓性/病毒性水样）；眼痛、畏光、流泪提示角膜炎或虹膜炎；无痛性视力骤降警惕青光眼、视网膜脱离、眼中风。', '突发无痛性视力丧失、眼外伤（异物扎入/化学伤——立即大量清水冲洗）、剧烈眼痛伴头痛呕吐（急性闭角型青光眼），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('ear', '耳痛 / 耳鸣 / 听力下降', '五官科', '通用', 'ent', '耳鼻喉头颈外科门诊', '', 'yellow', '["急性中耳炎","外耳道炎","分泌性中耳炎","突发性耳聋（72 小时内治疗关键）"]', '["全科医疗科门诊"]', '["耳朵进水侧头单脚跳排出，勿用棉签深挖。","感冒乘飞机、潜水时耳闷可做吞咽/捏鼻鼓气动作缓解。","突发耳聋尽早就医并做听力检查，不要等「自己好」。"]', '耳痛常因游泳进水、掏耳或感冒引起中耳炎/外耳道炎；突发单侧听力下降要高度警惕「突发性耳聋」，72 小时内治疗效果最好。', '耳部外伤后流血水、突发眩晕伴听力丧失，或耳后红肿剧痛，尽快就诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('nose', '鼻塞 / 流涕 / 打喷嚏', '五官科', '通用', 'ent', '耳鼻喉头颈外科门诊', '', 'green', '["过敏性鼻炎","急性鼻炎（感冒）","鼻窦炎","鼻中隔偏曲/鼻息肉（待排查）"]', '["呼吸与危重症医学科门诊（伴哮喘过敏）","儿科门诊（儿童鼻炎）"]', '["明确过敏原（过敏原检测），尘螨过敏可考虑脱敏治疗。","鼻用激素喷剂是鼻炎一线用药，按疗程使用副作用小，勿因顾虑停用。","反复单侧鼻出血或回吸涕带血，需做鼻内镜检查。"]', '过敏性鼻炎典型表现为阵发性喷嚏、清水样涕、鼻痒，常伴眼痒，与尘螨、花粉等过敏原相关；持续超过 10 天的黄脓涕、面部胀痛提示鼻窦炎。', '鼻出血量大不止（捏鼻翼压迫 10 分钟仍不止）或伴头晕，尽快急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('throat', '咽喉痛 / 声音嘶哑', '五官科', '通用', 'ent', '耳鼻喉头颈外科门诊', '', 'green', '["急性咽炎/扁桃体炎","急性喉炎","声带息肉/小结","咽喉反流（慢性）"]', '["全科医疗科门诊","呼吸与危重症医学科门诊"]', '["先多饮水、少说话、温盐水漱口；疼痛明显可含服润喉糖缓解。","声音嘶哑超过 2 周不缓解，务必做电子喉镜排查声带息肉/小结。","教师、主播等用嗓人群注意科学发声与嗓音休息。"]', '急性咽痛多为病毒感染，伴扁桃体脓点、高热时提示细菌感染需抗菌治疗；持续超过 2 周的声音嘶哑要警惕声带病变，需喉镜检查。', '剧烈咽痛伴张口困难、呼吸困难、流口水（扁桃体周围脓肿/喉梗阻可能），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('tooth', '牙痛 / 牙龈出血', '五官科', '通用', 'oral', '口腔医学中心（口腔全科门诊）', '医院口腔医学中心设口腔全科及牙体牙髓、牙周、颌面外科等专科门诊，按需分诊。', 'green', '["龋齿（蛀牙）","牙髓炎","智齿冠周炎","牙周炎","复发性口腔溃疡"]', '["耳鼻喉头颈外科门诊（颌面间隙感染）"]', '["蛀牙早补早好，牙髓炎多需根管治疗，拖延只会更贵更痛。","牙周炎重在定期洁牙与正确刷牙（巴氏刷牙法）维持。","智齿反复发炎建议炎症消退后评估拔除。"]', '牙痛剧烈、遇冷热加重多为牙髓炎；牙龈出血、牙齿松动多为牙周炎；智齿周围肿痛为冠周炎。口腔溃疡超过 2 周不愈合需警惕。', '面部明显肿胀伴发热、张口困难（颌面间隙感染可能），立即口腔颌面外科/急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('mental', '焦虑 / 抑郁情绪', '心理与全科', '成人', 'psych', '心身医学中心 / 四川省精神医学中心', '该中心门诊可评估情绪与心身疾病；部分病区位于温江院区，请以医院导诊指引为准。', 'green', '["焦虑障碍","抑郁障碍","适应障碍","躯体形式障碍（待评估）"]', '["全科医疗科门诊","神经内科门诊（失眠伴发）"]', '["持续超过 2 周、影响工作生活时建议专业评估，早干预效果好。","坚持适度运动、规律作息、减少刷手机，是辅助治疗的一部分。","药物起效需要 2–4 周，请遵医嘱复诊，勿自行停药。"]', '焦虑抑郁不只是「想开点」能解决的情绪问题，而是脑功能与神经递质失调相关的疾病，表现为持续低落、紧张担忧、兴趣减退并影响生活，规范治疗（心理+药物）有效。', '有伤害自己或他人的念头/行为时，请立即告知家人并拨打心理援助热线（如 12356）或前往急诊求助。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('physical-exam', '体检异常 / 慢病复诊', '心理与全科', '成人', 'general', '全科医疗科门诊', '多项轻度异常、暂不确定挂哪个专科时，先看全科做初筛最省事。', 'green', '["高血压","血脂异常","高尿酸血症/脂肪肝","代谢综合征（健康管理方向）"]', '["心血管内科门诊（确诊高血压）","内分泌科门诊","健康管理中心"]', '["带齐近 2 次体检报告就诊，对比变化趋势比单次数值更重要。","确诊慢病后建立健康档案，规律随访（血压血糖监测记录）。","先做生活方式调整（饮食、运动、减重）2–3 个月再复查评估。"]', '体检报告的「箭头」很多并非急症：轻度脂肪肝、血脂尿酸偏高可通过生活方式干预改善；血压、血糖异常需按流程复查确诊并建立长期管理。', '体检发现血压 ≥180/110mmHg 伴头痛胸闷，或新发明显不适，尽快心血管内科/急诊评估。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('mass', '乳房肿块', '外科肿瘤', '女性', 'breast', '乳腺外科 / 乳腺专病中心', '医院设乳腺专病中心，可完成乳腺超声、钼靶与活检的全程评估。', 'yellow', '["乳腺增生","乳腺纤维腺瘤","乳腺囊肿","乳腺癌（无痛性肿块，待排查）"]', '["妇科门诊","普外科/甲状腺外科门诊（就近评估）"]', '["自查时机：月经干净后 3–7 天，站立+平卧按外上→内上象限顺序触摸。","建议每年 1 次乳腺超声（40 岁以上加钼靶）筛查。","发现新发肿块或原有肿块增大，尽早做超声评估，勿拖延。"]', '多数乳房肿块是良性的（增生、纤维腺瘤、囊肿）。与月经周期相关的胀痛多为增生；无痛、质硬、边界不清、活动度差的肿块需重点排查乳腺癌。', '肿块伴皮肤橘皮样改变/凹陷、乳头血性溢液、腋窝淋巴结肿大，尽快乳腺专科就诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('joint-pain', '关节痛 / 关节肿', '骨科·风湿', '通用', 'rheum', '风湿免疫科门诊', '多关节、对称性肿痛或晨僵明显者优先看风湿免疫科；单个大关节退行性疼痛可看骨科。', 'green', '["骨关节炎","类风湿关节炎","痛风","反应性关节炎（待排查）"]', '["骨科门诊","内分泌科门诊（痛风）"]', '["就医前记录：哪些关节痛、是否对称、有无晨僵（>30 分钟有意义）、有无红肿发热。","痛风发作期避免进食高嘌呤食物，缓解期规范控制尿酸。","医生可能安排血尿酸、类风湿因子、抗 CCP 抗体及关节影像检查。"]', '关节痛病因多样：骨关节炎多见于中老年承重关节，活动后加重；类风湿关节炎呈对称性多关节肿痛伴晨僵；痛风常在夜间突发大脚趾红肿剧痛。', '单个关节突发红肿热痛伴高热（化脓性关节炎可能），或皮疹关节痛伴呼吸困难，尽快急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('renal-colic', '泌尿系结石 / 肾绞痛', '肾脏·泌尿', '通用', 'uro', '泌尿外科门诊', '典型的腰部或下腹部阵发性绞痛，沿输尿管向下腹部放射，多为结石移动所致。', 'yellow', '["肾结石","输尿管结石","泌尿系感染合并结石（待排查）"]', '["急诊医学科（疼痛剧烈/发热时）","肾内科门诊"]', '["疼痛发作时记录位置与放射方向，就医做泌尿系超声/CT 明确结石大小位置。","平时多饮水（每日 2000ml 以上）、少浓茶啤酒，是防结石的基础。","小结石（<6mm）多可保守排石，按医嘱复查位置变化。"]', '泌尿系结石在腰腹部表现为突发的剧烈绞痛，可伴恶心呕吐、血尿。小结石可通过多饮水自行排出，大结石或伴感染需碎石或手术处理。', '绞痛持续不止伴发热寒战（结石合并感染可能）、无尿或剧痛难忍，立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('varicose', '下肢静脉曲张（青筋）', '外科·血管', '成人（久站久坐人群高发）', 'vasc', '血管外科门诊', '', 'green', '["下肢静脉曲张","下肢深静脉功能不全","血栓性浅静脉炎（伴红肿硬结）"]', '["全科医疗科门诊","急诊医学科（突发肿痛）"]', '["避免久站久坐，间歇抬腿、穿医用弹力袜可缓解症状、延缓进展。","轻中度可保守治疗；明显曲张或有并发症者可行微创手术评估。","曲张静脉处突发红肿硬痛，警惕血栓性浅静脉炎，及时就医。"]', '静脉曲张是下肢静脉瓣膜功能不全导致血液倒流淤积，小腿出现蚯蚓状凸起，久站后沉重酸胀；长期不处理可继发皮肤变黑、溃疡。', '下肢突发明显肿胀、疼痛、皮肤发红发热（深静脉血栓可能）或曲张团块破裂出血，立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('head-injury', '头部外伤 / 撞到头', '外科·神经', '通用', 'nsurg', '神经外科门诊', '头部外伤后即使当时没事，也建议观察 24–48 小时；有昏迷史或高危因素者按医生要求复查头颅 CT。', 'yellow', '["头皮血肿/裂伤","脑震荡","颅内出血（需影像排查）"]', '["急诊医学科（急救中心，急性期）","神经内科门诊"]', '["头皮血肿 24 小时内冷敷，之后热敷促进吸收；伤口深或出血多需清创缝合（破伤风评估）。","伤后观察要点：是否嗜睡、频繁呕吐、剧烈头痛、肢体无力、言语异常。","服用抗凝药者、老年人、婴幼儿头部外伤即使不重也应就医评估。"]', '头部外伤常见头皮血肿与裂伤。脑震荡可表现为短暂意识不清、头晕、逆行性遗忘；「迟发性颅内出血」可能在受伤数小时后才出现症状，需高度警惕。', '撞击后意识丧失、喷射性呕吐、剧烈头痛加重、耳鼻流血水、瞳孔不等大，立即拨打 120——这是颅内出血的危急信号。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('emergency', '急危重症通用指引', '急诊急救', '通用', 'emerg', '急诊医学科（急救中心）', '本部急救中心 24 小时开诊，胸痛中心、卒中中心均设于此，直接前往急诊大厅，无需排队挂号。', 'red', '["急性心脑血管事件","严重创伤出血","中毒","急性过敏/哮喘危象（需现场急救）"]', '[]', '["先拨打 120 或由家属送医；心跳骤停者立即胸外按压（100–120 次/分）。","让患者平卧、保暖、保持气道通畅，不要喂水喂药。","带上既往病历与正在服用的药物清单，能帮医生快速判断。"]', '出现意识丧失、呼吸心跳骤停、大出血、严重呼吸困难、剧烈胸痛、中毒等情况，属于需要立即医疗干预的急危重症，每一分钟都影响预后。', '以下情况立即急诊：无反应/无呼吸、持续胸痛伴大汗、大口咯血呕血、抽搐不止、严重过敏喉头水肿、农药/药物中毒、严重烧烫伤或开放性骨折大出血。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('fatigue', '全身乏力 / 易疲劳', '全身与代谢', '通用', 'general', '全科医疗科门诊', '乏力多为非特异性表现，先挂全科做初步筛查，再按结果转诊到对应专科。', 'green', '["缺铁性贫血","甲状腺功能减退（待排查）","糖尿病（待排查）","慢性疲劳综合征"]', '["血液内科门诊","内分泌科门诊"]', '["记录乏力持续时间、加重时段与睡眠情况，就诊时一并告知医生。","伴头晕、面色苍白、怕冷或体重变化时，建议抽血查血常规、甲功和血糖。","贫血与甲减规范治疗后，乏力通常在数周内明显改善，不必焦虑。"]', '乏力指持续两周以上的精力不足、活动耐力下降，与“偶尔犯困”不同：它更持续，且休息后不易恢复。常见于贫血、甲状腺功能减退、糖尿病血糖异常、长期睡眠不足或情绪压力等，需要结合伴随症状找原因。', '乏力伴明显消瘦、反复低热、皮肤瘀斑或活动后气促，尽快就医排查血液或心肺疾病。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('lid-edema', '晨起眼睑浮肿', '肾脏泌尿', '通用', 'nephro', '肾内科门诊', '晨起眼睑浮肿是肾内科最常见的就诊线索之一，医生会先查尿常规确认有无蛋白尿或血尿。', 'yellow', '["肾小球肾炎","肾病综合征","甲状腺功能减退（待排查）","心功能不全（待排查）"]', '["全科医疗科门诊","心血管内科门诊"]', '["就诊前一天留意尿色与泡沫（蛋白尿的常见表现）。","不要自行服用利尿剂，会掩盖病情、干扰化验结果。","尿常规 + 肾功能 + 血压是最基本的初筛组合。"]', '眼睑组织疏松，水分容易在此滞留，晨起眼皮浮肿、午后逐渐消退，多提示肾性或甲状腺问题；若同时有下肢水肿、泡沫尿或血压升高，要优先排查肾脏。', '浮肿迅速加重、尿量明显减少或尿呈酱油色、伴气促不能平卧，立即到急诊医学科。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('dry-mouth', '口干口苦', '消化与代谢', '通用', 'digest', '消化内科门诊', '口苦多与夜间胃食管反流有关；若伴多饮多尿，需优先排查血糖。', 'green', '["胃食管反流病","糖尿病（待排查）","干燥综合征（待排查）","焦虑状态（待排查）"]', '["内分泌科门诊","风湿免疫科门诊","心身医学中心"]', '["晨起口苦明显者，睡前 3 小时少进食，睡觉时适当垫高枕头。","伴多饮多尿、体重下降时先查空腹血糖与糖化血红蛋白。","持续眼干、关节痛提示干燥综合征可能，需查自身抗体谱。"]', '口干口苦可因夜间胆汁或胃液反流、血糖升高引起的渗透性利尿，或干燥综合征使唾液分泌减少所致；若同时有多饮多尿、体重下降，应高度怀疑血糖异常。', '口干伴尿量骤增、恶心呕吐、呼吸有烂苹果味（警惕糖尿病酮症），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('night-sweat', '夜间盗汗', '发热与感染', '成人', 'fever', '感染科门诊', '盗汗是结核筛查的经典线索；同时伴低热、咳嗽或消瘦时应优先排查结核。', 'yellow', '["肺结核（需排查）","甲状腺功能亢进（待排查）","淋巴瘤（待排查）","更年期综合征（围绝经期女性）"]', '["呼吸与危重症医学科门诊","内分泌科门诊","全科医疗科门诊"]', '["记录体温、体重变化与出汗时间，就诊时提供给医生参考。","初筛通常包括胸片、血常规与甲功检查。","改善卧室通风与寝具即可，不建议用止汗类药物掩盖症状。"]', '盗汗指夜间入睡后异常出汗、醒后即止，常见于结核、甲亢、淋巴瘤或女性围绝经期。偶尔一次多与室温或被子有关，但持续时间长且伴体重下降、低热时需认真排查。', '盗汗伴长期低热、明显消瘦或颈部/腋窝无痛肿块迅速增大，尽早就诊；若同时咯血或明显呼吸困难，立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('sore-throat', '咽喉痛', '五官科', '通用', 'ent', '耳鼻喉头颈外科门诊', '伴发热、鼻塞多为呼吸道感染，轻症也可在呼吸内科或全科就诊。', 'green', '["急性咽炎","急性扁桃体炎","上呼吸道感染","疱疹性咽峡炎（儿童）"]', '["感染科门诊（发热门诊）","全科医疗科门诊"]', '["多喝温水、少说话，可用淡盐水漱口缓解。","伴发热超 3 天或咽部有白色脓点，建议就诊。","反复咽喉痛伴烧心，需排查胃食管反流。"]', '咽喉痛多由病毒或细菌感染引起，如咽炎、扁桃体炎；也可因干燥、用嗓过度、反流刺激所致。一般 3-7 天可自愈，化脓性扁桃体炎需抗生素治疗。', '咽痛剧烈伴张口困难、呼吸困难、流口水（警惕扁桃体周围脓肿/急性会厌炎），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('chronic-cough', '慢性咳嗽', '呼吸系统', '成人', 'resp', '呼吸与危重症医学科门诊', '超过 8 周的咳嗽属慢性咳嗽，病因多不在“肺”而在鼻、咽、胃，需系统排查。', 'yellow', '["咳嗽变异性哮喘","胃食管反流病","慢性支气管炎","鼻后滴漏综合征（待排查）"]', '["消化内科门诊","耳鼻喉头颈外科门诊"]', '["记录咳嗽与体位、进食、季节的关系，就诊时告知医生。","有吸烟史者需做肺功能与胸部 CT 排查慢阻肺。","夜间平躺加重者建议先排查反流与鼻炎。"]', '慢性咳嗽指咳嗽持续超过 8 周，最常见原因是咳嗽变异性哮喘、鼻后滴漏与胃食管反流，三者占八成以上。治疗关键是找准病因而非一味止咳。', '慢性咳嗽突然加重伴咯血、胸痛、呼吸困难或体重明显下降，尽快就诊，警惕肺部占位。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('snoring', '打鼾 / 睡眠呼吸暂停', '五官科', '成人', 'ent', '耳鼻喉头颈外科门诊', '评估打鼾可先挂耳鼻喉科；确诊睡眠呼吸暂停需做睡眠监测，医院设睡眠中心。', 'yellow', '["阻塞性睡眠呼吸暂停综合征","鼻中隔偏曲","扁桃体肥大","肥胖相关鼾症"]', '["心身医学中心","呼吸与危重症医学科门诊"]', '["侧卧睡眠、减重、睡前禁酒常可减轻症状。","白天困倦明显或伴晨起头痛者应做多导睡眠监测。","儿童长期打鼾需排查腺样体肥大，可影响面容与发育。"]', '响亮且不规律的打鼾、夜间憋醒、白天嗜睡提示阻塞性睡眠呼吸暂停。长期缺氧会增加高血压、房颤、脑卒中的风险，需通过睡眠监测评估。', '鼾声中断伴家人呼之不应、胸壁起伏停止，或白天驾车时不可控犯困，尽快就医评估。')
SELECT 1 FROM DUAL;

INSERT ALL
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('hypertension', '血压升高 / 高血压', '心脑血管', '成人', 'cardio', '心血管内科门诊', '首次确诊或血压波动大请挂心血管内科；仅复诊开药也可在社区或全科完成。', 'green', '["原发性高血压","高血压亚急症（待评估）","继发性高血压（需排查）","白大衣高血压"]', '["全科医疗科门诊","肾内科门诊（伴蛋白尿/肌酐升高时）","内分泌科门诊（伴低钾/年轻发病时）"]', '["家庭自测血压：安静休息 5 分钟后测量，早晚各一次并记录。","低盐饮食（每日 <5g 盐）、规律运动、控制体重。","已服药者勿自行停药或加量，复诊带好血压记录本。"]', '非同日三次诊室血压 ≥140/90mmHg 即考虑高血压。多数为原发性，需长期生活方式干预与规律服药；年轻、难治或伴低钾者要排查继发原因。', '血压 ≥180/120mmHg 伴剧烈头痛、胸痛、视力模糊、气短或意识改变（高血压急症），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('calf-swelling', '单侧小腿肿痛', '外科·血管', '成人', 'vasc', '血管外科门诊', '单侧突发肿胀伴疼痛是深静脉血栓的典型信号，需尽快评估，防止血栓脱落。', 'yellow', '["深静脉血栓（需排查）","下肢静脉曲张","蜂窝织炎（待排查）","肌肉拉伤"]', '["急诊医学科（呼吸困难时）","骨科门诊（有外伤史）"]', '["疑血栓时不要按摩、热敷或用力活动患肢。","久坐长途旅行者每隔 1 小时起身活动，多饮水。","肿胀伴发热、皮温高且边界不清，提示感染可能。"]', '单侧小腿突发肿胀、胀痛、皮肤发红发热，需警惕深静脉血栓，常见于久坐、手术后、妊娠或肿瘤患者；血栓脱落可致肺栓塞，属急症。', '患肢肿胀同时突发胸痛、咯血、呼吸困难（警惕肺栓塞），立即拨打 120。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('bloating', '腹胀', '消化系统', '通用', 'digest', '消化内科门诊', '无明显腹痛的慢性腹胀首选消化内科；伴腹围明显增大者需尽快就诊。', 'green', '["功能性消化不良","肠易激综合征","慢性胃炎","便秘"]', '["全科医疗科门诊","胃肠外科门诊（疑肠梗阻时）"]', '["少食产气食物（豆类、碳酸饮料、高淀粉），细嚼慢咽。","记录腹胀与进食、排便的关系，帮助判断病因。","规律运动与腹部按摩可促进排气。"]', '腹胀常见于消化不良、肠易激综合征与便秘，多与饮食、情绪和肠道菌群有关。若腹胀持续加重、腹围明显增大或伴消瘦，需排查器质性疾病。', '腹胀剧烈伴停止排气排便、呕吐、剧烈腹痛（警惕肠梗阻），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('dysphagia', '吞咽困难 / 吞咽异物感', '消化系统', '通用', 'digest', '消化内科门诊', '进行性加重的吞咽困难是报警症状，医生多会建议胃镜检查明确病因。', 'yellow', '["食管炎","贲门失弛缓症（待排查）","食管狭窄","食管肿瘤（需排查）"]', '["耳鼻喉头颈外科门诊（咽喉部梗阻感）","神经内科门诊（伴饮水呛咳）"]', '["流质饮食过渡，避免干硬大块食物。","进行性加重或伴消瘦、黑便，务必尽快做胃镜。","老年人突发呛咳需警惕脑血管病与误吸。"]', '吞咽困难分口咽性与食管性两类：前者伴饮水呛咳、发音不清，多与神经肌肉病有关；后者呈胸骨后阻挡感，进行性加重提示食管器质性病变，需胃镜排查。', '完全不能进食进水、伴剧烈胸痛或呕血，立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('hemorrhoid', '便血 / 痔疮', '消化系统', '通用', 'giSurg', '胃肠外科门诊', '便血首诊胃肠外科做肛门指检+肠镜评估；勿想当然当作痔疮而延误肠道肿瘤。', 'yellow', '["内痔","肛裂","结直肠息肉","结直肠肿瘤（需排查）"]', '["消化内科门诊","急诊医学科（大量出血时）"]', '["记录血的颜色、量、是否与大便混合，就诊时告知医生。","肛裂多伴排便剧痛；痔疮脱出可温水坐浴缓解。","大便习惯改变（变细/次数增多）者应尽早肠镜。"]', '便血原因从痔疮、肛裂到息肉、结直肠肿瘤不等。鲜红血液多来自肛门直肠（痔/裂），暗红混便或伴黏液需警惕结肠病变，45 岁以上新发便血建议结肠镜。', '大量便血伴头晕、面色苍白、心率快（失血性休克前兆），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('proteinuria', '泡沫尿 / 蛋白尿', '肾脏泌尿', '通用', 'nephro', '肾内科门诊', '尿检发现蛋白尿需肾内科评估，必要时做 24 小时尿蛋白定量。', 'yellow', '["肾小球肾炎","肾病综合征（待评估）","高血压肾损害","生理性蛋白尿"]', '["内分泌科门诊（伴糖尿病时）","心血管内科门诊（伴高血压时）"]', '["先复查晨尿+尿微量白蛋白/肌酐比，避免过度紧张。","伴眼睑或下肢浮肿、血压升高者应尽快肾内科就诊。","已确诊者遵医嘱控盐、控蛋白、规律复查。"]', '尿液表面细密且久不消散的泡沫提示蛋白尿可能，可见于肾炎、肾病综合征、糖尿病或高血压肾损害；剧烈运动、发热也可出现一过性蛋白尿。', '尿量骤减（少尿/无尿）、全身明显水肿、恶心呕吐伴血肌酐快速上升，立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('incontinence', '漏尿 / 尿失禁', '肾脏泌尿', '成人（女性多见）', 'uro', '泌尿外科门诊', '女性尿失禁可到泌尿外科或盆底康复门诊评估；医院设有女性泌尿与盆底专病方向。', 'green', '["压力性尿失禁","急迫性尿失禁","盆底功能障碍","前列腺增生（男性）"]', '["妇科门诊","康复医学科"]', '["凯格尔运动（缩肛训练）每日坚持 3 组，至少 3 个月见效。","控制体重、戒烟、避免长期便秘可减轻症状。","男性伴尿线细、夜尿多者需查前列腺。"]', '尿失禁分为压力性（咳嗽、大笑、跳跃时漏尿，多见于生育后女性）与急迫性（突然尿意憋不住）。多数可通过盆底肌训练、行为治疗或微创手术改善。', '突发完全无法排尿伴下腹剧痛（急性尿潴留），立即急诊导尿。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('prostate-symptoms', '排尿困难 / 夜尿增多', '肾脏泌尿', '中老年男性', 'uro', '泌尿外科门诊', '中老年男性排尿症状首选泌尿外科，常规做前列腺超声与 PSA 筛查。', 'green', '["良性前列腺增生","前列腺炎","前列腺肿瘤（需排查）","膀胱过度活动症"]', '["肾内科门诊","全科医疗科门诊"]', '["睡前减少饮水、避免咖啡浓茶，观察两周记录夜尿次数。","50 岁以上每年查一次 PSA+前列腺超声。","勿因“难为情”拖延，排尿梗阻可损伤肾功能。"]', '50 岁以上男性夜尿增多、尿线细、尿不尽，多与前列腺增生有关；前列腺炎多见于中青年，伴会阴坠胀。前列腺特异性抗原（PSA）异常升高需进一步排查肿瘤。', '完全排不出尿且下腹胀痛难忍（急性尿潴留），或全程肉眼血尿伴血块，立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('gout', '痛风 / 高尿酸', '骨科·风湿', '成人', 'rheum', '风湿免疫科门诊', '痛风急性发作可挂风湿免疫科或疼痛科；降尿酸长期管理也多由风湿科指导。', 'yellow', '["急性痛风性关节炎","高尿酸血症","慢性痛风石性关节炎"]', '["骨科门诊","肾内科门诊（伴结石/肾损时）","疼痛科门诊"]', '["急性期 24 小时内冷敷、抬高患肢、多饮水（每日 2000ml+）。","避免啤酒、海鲜、动物内脏等高嘌呤食物。","缓解期血尿酸应长期控制在 360μmol/L 以下。"]', '痛风是尿酸盐结晶沉积关节所致，典型发作是夜间大脚趾突发红肿热痛，与高嘌呤饮食、饮酒、受凉有关。急性期消炎止痛，缓解期规范降尿酸。', '关节红肿热痛伴发热寒战，或怀疑感染性关节炎时，尽快就诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('osteoporosis', '骨质疏松 / 易骨折', '骨科·风湿', '中老年（女性多见）', 'endo', '内分泌科门诊', '骨密度检测与抗骨质疏松治疗由内分泌科负责；已发生骨折者需骨科先处理。', 'green', '["原发性骨质疏松症","绝经后骨质疏松","椎体压缩性骨折（待排查）"]', '["骨科门诊","康复医学科"]', '["50 岁以上女性建议做一次骨密度筛查。","每日补充钙 1000mg 与维生素 D，坚持负重运动。","居家防跌倒：浴室防滑、夜间留灯、穿防滑鞋。"]', '骨质疏松是骨量流失导致骨骼变脆，绝经后女性与高龄老人高发，常以身高变矮、驼背或轻微外力骨折被发现。双能 X 线骨密度（DXA）是诊断金标准。', '摔倒或轻微外伤后腰背剧痛、无法站立（警惕椎体/髋部骨折），尽快骨科就诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('hyperlipidemia', '血脂异常', '内分泌', '成人', 'endo', '内分泌科门诊', '血脂管理多由内分泌科或心血管内科负责；伴冠心病、糖尿病者需更严格达标。', 'green', '["高胆固醇血症","高甘油三酯血症","混合型高脂血症"]', '["心血管内科门诊","全科医疗科门诊"]', '["空腹 8-12 小时抽血复查，避免误差。","少吃动物内脏、油炸食品与含糖饮料，每周运动 150 分钟。","确诊后规律服药，勿因化验“正常”擅自停药。"]', '血脂异常指胆固醇或甘油三酯升高，是动脉粥样硬化的核心危险因素。“坏胆固醇”（LDL-C）越高、危险因素越多，达标线越严，需按风险分层决定是否用药。', '甘油三酯 >5.6mmol/L 且饮酒/暴食后出现上腹痛（警惕急性胰腺炎），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('easy-bruise', '皮肤瘀斑 / 易出血', '血液', '通用', 'hemato', '血液内科门诊', '无明显外伤的瘀斑瘀点或出血倾向，首诊血液内科查血常规与凝血。', 'yellow', '["血小板减少症","过敏性紫癜","凝血功能异常","维生素缺乏"]', '["皮肤科（皮疹为主时）","全科医疗科门诊"]', '["观察出血点是否按压力不褪色，拍照记录范围变化。","近期避免服用阿司匹林等影响凝血的药物。","伴关节肿痛或腹痛的紫癜需排查过敏性紫癜。"]', '皮肤出现针尖样出血点（瘀点）或大片瘀斑，可因血小板减少、凝血因子缺乏或血管炎引起。轻者可能是碰撞或维生素 C 缺乏，但反复出血需查血常规与凝血功能。', '皮肤瘀斑伴牙龈渗血不止、鼻血难止、黑便或颅内症状（剧烈头痛、呕吐），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('morning-stiffness', '关节晨僵', '骨科·风湿', '通用', 'rheum', '风湿免疫科门诊', '晨僵超过 1 小时且伴双手对称小关节肿痛，是类风湿关节炎的经典信号。', 'yellow', '["类风湿关节炎（需排查）","骨关节炎","强直性脊柱炎（腰背晨僵）"]', '["骨科门诊","康复医学科"]', '["记录晨僵持续时间与受累关节，就诊时告知医生。","抽血查类风湿因子、抗 CCP 抗体帮助确诊。","晨起温水泡手、轻柔活动关节可缓解僵硬。"]', '晨僵指早晨起床后关节僵硬、活动困难，半小时内缓解多为骨关节炎，超过 1 小时且伴对称性手部小关节肿痛提示类风湿关节炎，早诊早治可避免关节变形。', '单个关节突发红肿热痛伴高热（警惕化脓性关节炎），尽快就诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('heel-pain', '足跟痛', '骨科运动', '通用', 'ortho', '骨科门诊', '足底筋膜炎在骨科或康复科均可评估；顽固性疼痛可考虑冲击波等治疗。', 'green', '["足底筋膜炎","跟腱炎","跟骨骨刺","跟痛症"]', '["康复医学科","疼痛科门诊"]', '["晨起前先做足底与小腿拉伸再下地。","选有足弓支撑的鞋，避免赤脚踩硬地。","症状超 3 个月不缓解可考虑冲击波治疗。"]', '足跟痛最常见是足底筋膜炎：晨起下地第一步剧痛、走几步缓解、久站久走后加重。多与久站、肥胖、鞋底过平或运动过量有关，多数通过拉伸与康复训练改善。', '足跟红肿热痛伴发热，或外伤后剧痛不能负重，尽快就诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('frozen-shoulder', '肩痛 / 活动受限', '骨科运动', '中老年（40-60 岁）', 'ortho', '骨科门诊', '肩痛需区分肩周炎与肩袖损伤（治疗相反），骨科查体+核磁可明确。', 'green', '["肩周炎（冻结肩）","肩袖损伤","肩峰撞击综合征","颈椎病放射痛"]', '["疼痛科门诊","康复医学科"]', '["急性疼痛期减少提重物，冷敷控制炎症。","明确诊断前勿强行大幅度抡肩锻炼。","糖尿病者冻结肩风险更高，需同时控糖。"]', '肩痛不一定都是“肩周炎”：肩袖损伤多见于抬肩无力伴夜间痛，肩周炎则主动被动活动都受限。两者治疗方向不同，盲目爬墙锻炼可能加重肩袖撕裂。', '外伤后肩部剧痛、手臂完全不能动或肩关节变形，尽快骨科就诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('sciatica', '坐骨神经痛 / 腿麻', '骨科运动', '通用', 'ortho', '骨科门诊', '腰痛伴下肢放射痛、麻木提示神经受压，骨科查腰椎 MRI 明确。', 'yellow', '["腰椎间盘突出症","腰椎管狭窄症","梨状肌综合征","带状疱疹后神经痛（需区分）"]', '["疼痛科门诊","神经外科门诊（出现马尾综合征时）"]', '["急性期卧硬板床休息 2-3 天，避免弯腰搬重物。","避免久坐，每 30-40 分钟起身活动。","保守治疗 6 周无效或症状加重者复诊评估。"]', '坐骨神经痛表现为臀部向大腿后侧、小腿放射的疼痛麻木，多由腰椎间盘突出压迫神经根引起。多数可保守治疗缓解，出现大小便障碍时需急诊手术。', '腰痛伴会阴部麻木、大小便失禁/潴留（马尾综合征），或下肢进行性无力，立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('memory-loss', '记忆力下降', '神经系统', '中老年', 'neuro', '神经内科门诊', '省医院神经内科设记忆门诊，专病评估早期认知下降。', 'yellow', '["轻度认知障碍","阿尔茨海默病（需评估）","血管性认知障碍","焦虑抑郁所致假性痴呆"]', '["心身医学中心","全科医疗科门诊"]', '["家属陪同就诊，详细描述发病时间与行为变化。","完成认知量表+头颅 MRI 评估，排除可逆病因。","坚持脑力活动、社交与运动，控制三高。"]', '记忆力下降需区分正常老化与病理改变：近期记忆明显减退、影响生活、性格改变或定向力障碍应尽早就医。部分原因（甲减、维生素缺乏、抑郁）是可逆的。', '突然出现的意识混乱、言语不清或不能认出家人（急性谵妄/卒中），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('tremor', '手抖 / 震颤', '神经系统', '通用', 'neuro', '神经内科门诊', '震颤类型判断（静止性/动作性）对病因很关键，神经内科查体即可初步区分。', 'green', '["特发性震颤","帕金森病（需评估）","甲状腺功能亢进（待排查）","焦虑所致震颤"]', '["内分泌科门诊","心身医学中心"]', '["录一段手抖视频（静止/持物/写字各一段）就诊时给医生看。","减少咖啡因摄入，观察饮酒后变化（特发性震颤可暂缓）。","帕金森病早期药物控制效果好，勿拖延。"]', '手抖分动作性震颤（拿东西时抖，多为特发性震颤）与静止性震颤（手放腿上抖、活动时减轻，提示帕金森病）。年轻者手抖还应排查甲亢与焦虑。', '突发单侧肢体抖动伴口角歪斜、言语不清、肢体无力（警惕卒中），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('facial-paralysis', '面瘫 / 口角歪斜', '神经系统', '通用', 'neuro', '神经内科门诊', '突发口角歪斜必须第一时间排除脑卒中；无肢体无力者多为周围性面瘫，神经内科诊治。', 'red', '["周围性面神经麻痹（贝尔面瘫）","脑梗死（需紧急排查）","中耳炎并发症（待排查）"]', '["急诊医学科（伴肢体无力/言语不清时）","耳鼻喉头颈外科门诊（伴耳痛耳后痛时）"]', '["突然嘴歪先做卒中自测（笑一笑/举双臂/说句话），任一异常立即 120。","贝尔面瘫发病 72 小时内激素治疗效果最好。","闭眼不全者白天戴眼罩、睡前涂眼膏防角膜损伤。"]', '面瘫分两种：周围性面瘫（贝尔面瘫）表现为同侧额纹消失、闭眼不全、鼓腮漏气；中枢性面瘫（脑梗死等）多仅下半面瘫且伴肢体无力。区分二者决定是否按卒中急救。', '口角歪斜伴单侧肢体无力、言语不清、视物重影或意识改变，立即拨打 120。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('anxiety', '焦虑紧张', '心理与全科', '通用', 'psych', '心身医学中心', '心慌、胸闷反复发作但心脏检查正常者，建议到心身医学中心评估焦虑相关问题。', 'green', '["广泛性焦虑障碍","惊恐障碍","躯体化障碍","甲状腺功能亢进（待排查）"]', '["心血管内科门诊（先排除心脏问题）","内分泌科门诊"]', '["深呼吸练习（吸气 4 秒-屏气 4 秒-呼气 6 秒）可缓解急性紧张。","规律睡眠、减少咖啡因、坚持运动是基础治疗。","症状持续影响工作生活时应尽早专业评估，勿硬扛。"]', '焦虑障碍表现为过度紧张担忧、心慌、出汗、坐立不安，常伴躯体不适（心慌、气短、胃肠紊乱）。先排除甲亢与心脏疾病后，心理评估与治疗多数效果良好。', '突发强烈恐惧伴濒死感、胸痛大汗（惊恐发作/心梗需鉴别），反复发作请尽快就医。')
SELECT 1 FROM DUAL;

INSERT ALL
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('depression', '情绪低落 / 抑郁', '心理与全科', '通用', 'psych', '心身医学中心', '持续 2 周以上的情绪低落、兴趣减退伴睡眠食欲改变，建议到心身医学中心/精神科评估。', 'yellow', '["抑郁发作","双相情感障碍（需评估）","甲状腺功能减退（待排查）","季节性情绪障碍"]', '["全科医疗科门诊","内分泌科门诊"]', '["若出现“不想活”念头，请立即告知家人并就医，或拨打心理援助热线。","坚持规律作息与日照，每天外出活动 30 分钟。","遵医嘱规律服药 2-4 周起效，勿因“没立刻好”自行停药。"]', '抑郁的核心表现是持续情绪低落、兴趣减退与精力下降，常伴失眠早醒、食欲改变、自责无望。它是有生物学基础的疾病，药物与心理治疗均有效，早诊早治很重要。', '表达自杀计划、行为异常或已出现自伤行为时，需 24 小时有人陪伴并立即就医/拨打 120。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('hives', '荨麻疹 / 风团', '皮肤科', '通用', 'derm', '皮肤科（皮肤病性病研究所）', '荨麻疹属皮肤科常见病；反复超过 6 周为慢性荨麻疹，可做过敏原评估。', 'green', '["急性荨麻疹","过敏性皮炎","血管性水肿（待排查）"]', '["全科医疗科门诊","急诊医学科（喉头水肿时）"]', '["回忆发作前 4 小时内接触的食物与药物，写日记找诱因。","口服二代抗组胺药（如氯雷他定）可控制症状。","避免搔抓与热水烫洗，穿宽松棉质衣物。"]', '荨麻疹是过敏或刺激使皮肤肥大细胞释放组胺所致，表现为瘙痒性风团，来去迅速，多数 24 小时内消退。诱因包括食物、药物、感染、冷热与压力。', '风团伴口唇、眼睑肿胀、声音嘶哑、呼吸困难（喉头水肿）或头晕休克，立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('herpes-zoster', '带状疱疹（缠腰龙）', '皮肤科', '中老年', 'derm', '皮肤科（皮肤病性病研究所）', '发病 72 小时内抗病毒治疗可显著减少后遗神经痛；水疱消退后仍痛可转疼痛科。', 'yellow', '["带状疱疹","带状疱疹后神经痛","单纯疱疹（需区分）"]', '["疼痛科门诊","神经内科门诊"]', '["72 小时内开始抗病毒治疗，效果最好。","水疱期保持清洁干燥，勿挑破防继发感染。","50 岁以上可接种带状疱疹疫苗预防。"]', '带状疱疹是潜伏的水痘-带状疱疹病毒再激活所致，沿单侧神经分布出现簇集水疱伴烧灼刺痛，“先痛后疱”是其特点。中老年、免疫力低下者高发，易遗留神经痛。', '疱疹累及眼部、耳部（伴面瘫/眩晕）或头面部大面积，尽快就诊；出现高热、精神差立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('pigment-change', '皮肤色素痣 / 白斑', '皮肤科', '通用', 'derm', '皮肤科（皮肤病性病研究所）', '痣出现“不对称、边缘不齐、颜色不均、直径增大”任一变化，尽早皮肤科面诊。', 'green', '["色素痣（需监测）","白癜风","花斑癣","恶性黑色素瘤（需排查）"]', '["皮肤外科/整形外科（需手术切除时）"]', '["每季度自查一次全身痣的变化，拍照留存对比。","避免反复抠抓、摩擦易受刺激部位的痣。","防晒是预防色素性疾病的第一道防线。"]', '多数色素痣为良性，但出现 ABCDE 变化（不对称、边缘不规则、颜色不均、直径 >6mm、近期变化）需排查恶性黑色素瘤。白斑则需区分白癜风与花斑癣。', '痣短期内迅速增大、破溃出血、周围出现卫星状小黑点，尽快皮肤专科就诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('nail-fungus', '灰指甲 / 脚气', '皮肤科', '通用', 'derm', '皮肤科（皮肤病性病研究所）', '灰指甲需真菌镜检确诊后规范口服/外用抗真菌药，疗程较长。', 'green', '["甲癣（灰指甲）","足癣（脚气）","手癣","甲营养不良（需区分）"]', '["全科医疗科门诊"]', '["保持足部干燥，穿透气鞋袜，毛巾拖鞋专人专用。","灰指甲口服抗真菌药需监测肝功能，遵医嘱复查。","家人同治、环境消毒可防再感染。"]', '脚气与灰指甲同属真菌感染（皮肤癣菌）。脚气表现为趾间脱皮、水疱、瘙痒；灰指甲表现为指甲增厚、变黄、浑浊。真菌镜检可确诊，治疗需坚持足够疗程。', '足部红肿热痛、流脓伴发热（继发细菌感染/丹毒），尽快就诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('vision-blur', '视物模糊 / 视力下降', '五官科', '通用', 'oph', '眼科门诊', '视力渐进下降应到眼科查屈光与眼底；糖尿病患者每年至少查一次眼底。', 'yellow', '["屈光不正","白内障","糖尿病视网膜病变（需排查）","青光眼（需排查）"]', '["内分泌科门诊（伴糖尿病时）","神经内科门诊（伴视野缺损时）"]', '["记录发病缓急、单眼/双眼、是否伴眼痛，就诊时告知。","糖尿病患者每年散瞳查眼底。","阳光强烈时戴防紫外线镜，延缓白内障。"]', '视物模糊原因众多：年轻人多为屈光不正，中老年常见白内障，糖尿病者需警惕视网膜病变。突发或短期内明显下降的视力问题，尤其伴眼痛时需尽快就医。', '突发单眼无痛性视力骤降、眼前像拉窗帘遮挡，或剧烈眼痛伴恶心呕吐（急性闭角型青光眼），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('eye-floaters', '眼前黑影 / 飞蚊症', '五官科', '通用', 'oph', '眼科门诊', '黑影突然增多伴闪光感，可能视网膜裂孔/脱离前兆，需当天散瞳查眼底。', 'yellow', '["玻璃体混浊","视网膜脱离（需紧急排查）","后葡萄膜炎","视网膜裂孔（需排查）"]', '["急诊医学科（夜间突发时）"]', '["黑影量突发增多或伴闪光，48 小时内务必散瞳查眼底。","高度近视者避免剧烈对抗运动与蹦极。","单纯飞蚊不影响视力者定期随访即可。"]', '眼前飘动的半透明黑影多为玻璃体混浊（飞蚊症），近视与老年人常见，多数无害。但黑影突然大量增多、伴闪光或固定黑影遮挡，提示视网膜裂孔/脱离风险。', '视野出现固定黑幕样遮挡、视力骤降（视网膜脱离），尽快急诊眼科处理。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('hearing-loss', '听力下降 / 耳聋', '五官科', '通用', 'ent', '耳鼻喉头颈外科门诊', '突发听力下降（尤其 72 小时内）需尽快就诊，越早治疗效果越好。', 'yellow', '["突发性耳聋","老年性耳聋（感音神经性）","分泌性中耳炎","耵聍栓塞"]', '["神经内科门诊"]', '["突发听力下降务必 1 周内就诊，勿等“自己好”。","避免长时间大音量戴耳机（60/60 原则）。","老人听力下降可评估助听器，改善生活质量。"]', '突发性耳聋指短时间内（多 3 天内）单耳听力明显下降，属耳科急症，黄金治疗期为发病 72 小时至 1 周内。渐进性下降则多为老年性或噪声性耳聋。', '突发耳聋伴眩晕、面瘫，或头部外伤后耳道流血水，尽快急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('epistaxis', '鼻出血', '五官科', '通用', 'ent', '耳鼻喉头颈外科门诊', '反复鼻出血或止血困难者就诊耳鼻喉科；中老年高血压者出血常与血压相关。', 'green', '["鼻黏膜干燥糜烂","鼻中隔偏曲","高血压相关鼻出血","血液系统疾病（需排查）"]', '["血液内科门诊（伴牙龈出血/瘀斑时）","急诊医学科（出血量大时）"]', '["止血姿势：坐直身体前倾，捏紧鼻翼 10 分钟，勿仰头。","干燥季节用生理盐水喷鼻或涂红霉素软膏保湿。","控制血压，避免用力擤鼻与挖鼻。"]', '鼻出血多因鼻前部黏膜干燥、抠鼻或用力擤鼻引起，低头压迫鼻翼 10 分钟多可止住。反复大量出血或同时有多处出血倾向时需排查高血压与血液病。', '鼻血 20 分钟按压不止、口吐鲜血或面色苍白头晕（失血较多），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('mouth-ulcer', '口腔溃疡', '五官科', '通用', 'oral', '口腔医学中心（口腔全科）', '普通口腔溃疡两周内自愈；超过两周不愈合的溃疡需到口腔科排查。', 'green', '["复发性阿弗他溃疡","创伤性溃疡","白塞病（反复多部位溃疡时）","口腔肿瘤（久不愈合需排查）"]', '["全科医疗科门诊","风湿免疫科门诊（疑白塞病时）"]', '["溃疡期避免辛辣烫硬食物，可用含漱液与溃疡贴缓解。","反复发作者查维生素 B12、叶酸与铁蛋白。","戒烟限酒、保证睡眠可减少复发频率。"]', '口腔溃疡多为复发性阿弗他溃疡，与免疫、压力、营养与遗传有关，一般 7-14 天自愈。同一位置超过 2-3 周不愈合、质地变硬或面积增大者需排查恶变。', '溃疡超过 3 周不愈、明显变硬或伴颈部淋巴结肿大，尽快口腔专科检查。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('gum-bleeding', '牙龈出血', '五官科', '通用', 'oral', '口腔医学中心（口腔全科）', '刷牙出血多为牙龈炎/牙周炎，需洁牙与牙周治疗；同时伴皮肤瘀斑者查血。', 'green', '["牙龈炎","牙周炎","牙结石","血小板减少（需排查）"]', '["血液内科门诊","耳鼻喉头颈外科门诊"]', '["坚持正确刷牙（巴氏刷牙法）+ 牙线，每 6-12 个月洁牙一次。","出血明显时用软毛牙刷，勿因出血而不敢刷。","伴皮肤瘀斑、鼻血不止者先查血常规与凝血。"]', '牙龈出血最常见原因是牙菌斑堆积导致牙龈炎，表现为刷牙或咬硬物出血、牙龈红肿。及时洁牙（洗牙）并保持口腔清洁可恢复；伴随多处出血倾向需查血。', '牙龈自发性大量渗血难以止住，或伴发热、皮肤广泛瘀点（警惕血液病/急性感染），尽快就诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('dysmenorrhea', '痛经', '妇产', '女性', 'gyn', '妇科门诊', '痛经逐年加重或止痛药无效者，需妇科超声排查内异症与腺肌症。', 'green', '["原发性痛经","子宫内膜异位症（需评估）","子宫腺肌症","盆腔炎（伴发热时）"]', '["全科医疗科门诊"]', '["月经来潮前 1-2 天开始热敷下腹，可减轻痉挛。","布洛芬等止痛药按说明书在痛前或痛初服用。","放环（曼月乐）或口服短效避孕药可治顽固痛经，需医生评估。"]', '痛经分原发（无器质病变，年轻女性多见）与继发（由内异症、腺肌症等引起，常逐年加重）。止痛药在疼痛刚开始时服用效果最好。', '突发剧烈下腹痛（非经期/剧烈运动后）伴面色苍白、晕厥（警惕宫外孕/囊肿破裂），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('amenorrhea', '月经不调 / 闭经', '妇产', '女性', 'gyn', '妇科门诊', '月经推迟先排除妊娠；连续 3 个周期紊乱或闭经超 3 个月建议妇科就诊。', 'green', '["多囊卵巢综合征","排卵障碍","甲状腺功能异常（待排查）","早发性卵巢功能不全（需评估）"]', '["内分泌科门诊","全科医疗科门诊"]', '["记录月经周期（App/日历）至少 3 个月，就诊时展示。","闭经伴溢乳者查泌乳素；伴多毛痤疮者查雄激素。","规律作息、适度体重与运动有助于恢复排卵。"]', '月经推迟或闭经原因多样：育龄期先排除妊娠；多囊卵巢综合征表现为月经稀发+多毛痤疮；过度节食、运动过量、压力与甲状腺异常均可影响排卵。', '停经后突发剧烈下腹痛伴阴道出血、晕厥（警惕异位妊娠破裂），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('menopause', '更年期综合征', '妇产', '女性（45-55 岁）', 'gyn', '妇科门诊', '省医院妇科设更年期/绝经管理方向，可评估激素治疗指征。', 'green', '["围绝经期综合征","睡眠障碍","焦虑抑郁状态（待评估）","骨质疏松风险"]', '["心身医学中心","内分泌科门诊"]', '["潮热发作时注意通风、穿分层衣物方便穿脱。","补充钙与维生素 D，负重运动防骨质疏松。","症状严重或影响生活时咨询专科，勿自行买激素服用。"]', '围绝经期因雌激素波动下降，出现潮热、盗汗、失眠、情绪波动与月经紊乱，可持续数年。严重者经评估可行绝经激素治疗（MHT）或中医药调理。', '更年期出血量大、淋漓不断超过 2 周或绝经后再次出血，尽快妇科检查排除内膜病变。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('infertility', '备孕未孕', '妇产', '育龄夫妻', 'gyn', '妇科门诊', '规律同房未避孕一年（35 岁以上半年）未孕，夫妻双方到妇科/生殖门诊共同评估。', 'green', '["排卵障碍","输卵管因素不孕（待排查）","男方少弱精症","不明原因不孕"]', '["泌尿外科门诊（男方因素）","内分泌科门诊"]', '["男方先查精液常规（便宜无创），再查女方。","用排卵试纸/监测找准排卵期，放松心态。","35 岁以上备孕超过半年未孕即可提前评估。"]', '不孕指规律性生活未避孕 1 年未孕，女方因素（排卵、输卵管、子宫）与男方因素约各占四成。评估讲究顺序：男方精液 → 女方排卵 → 输卵管造影。', '无紧急红线；但促排卵治疗中出现下腹剧痛、腹胀明显（卵巢过度刺激风险），及时联系医生。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('fetal-movement', '胎动异常', '妇产', '孕妇（孕晚期）', 'ob', '产科门诊', '孕 28 周后应规律数胎动；明显减少或消失属紧急情况，直接到产科急诊。', 'red', '["胎儿宫内缺氧（需紧急评估）","胎儿睡眠周期","胎盘功能减退（需评估）"]', '["急诊医学科（夜间）"]', '["每天固定时间数胎动，侧卧位计数最敏感。","胎动减少时先吃甜食、左侧卧 1 小时再数一次。","有明显减少记录具体时间，尽快产科评估。"]', '孕 28 周后胎动规律性增强，建议每日早中晚各数 1 小时。胎动较平时减少一半以上或完全消失，是胎儿宫内缺氧的重要信号，需尽快做胎心监护与超声。', '胎动完全消失 12 小时以上，或伴腹痛、阴道流血/流水，立即产科急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('child-rash', '儿童皮疹', '儿科', '儿童（≤14 岁）', 'pedi', '儿科门诊', '儿童皮疹多伴发热，需儿科医生鉴别传染病与过敏；疑手足口、水痘等传染性出疹先电话咨询。', 'yellow', '["幼儿急疹","手足口病","水痘","麻疹/猩红热（待排查）","过敏性皮疹"]', '["皮肤科（皮肤病性病研究所）","发热门诊（夜间）"]', '["出疹期间记录体温与皮疹顺序、形态，拍照给医生看。","手足口病患儿注意口腔护理与隔离，防脱水。","水痘患儿剪短指甲防抓破感染，禁用阿司匹林退热。"]', '儿童出疹性疾病多伴发热：热退疹出多为幼儿急疹；发热伴口腔疱疹、手足疱疹为手足口病；水痘呈向心性水疱伴瘙痒。多数自限，但需鉴别重症。', '皮疹伴持续高热不退、精神萎靡、抽搐、呼吸急促或皮疹呈出血性（按压不褪色），立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('child-growth', '身材矮小 / 发育迟缓', '儿科', '儿童（≤14 岁）', 'pedi', '儿科门诊', '省医院儿科有儿童生长发育/内分泌方向，评估矮小与性早熟。', 'green', '["生长激素缺乏症（需评估）","体质性青春期延迟","家族性矮小","性早熟（需排查）"]', '["内分泌科门诊","全科医疗科门诊"]', '["连续记录每半年身高体重，画生长曲线。","就诊前拍左手骨龄片，带既往身高记录。","保证睡眠（生长激素夜间分泌）、均衡营养与运动。"]', '判断矮小需对照同年龄同性别身高标准差：低于 P3 或年增长 <5cm（3 岁-青春期）应评估。骨龄片是核心检查，生长激素缺乏、甲状腺功能、性早熟均可影响。', '无急诊红线；但女孩 8 岁前、男孩 9 岁前出现第二性征（性早熟）应尽快专科评估。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('child-bedwetting', '儿童遗尿（尿床）', '儿科', '儿童（≥5 岁）', 'pedi', '儿科门诊', '5 岁以上仍频繁尿床可就诊儿科或儿童遗尿门诊评估。', 'green', '["原发性夜间遗尿症","膀胱功能异常（需评估）","泌尿系感染（伴白天尿频时）"]', '["泌尿外科门诊","小儿外科门诊"]', '["睡前 2 小时限水、睡前排尿，建立奖励机制不责骂。","记录尿床频率与饮水规律，就诊时展示。","遗尿报警器（尿湿即响）对多数孩子有效，坚持 3 个月。"]', '5 岁以上儿童每周尿床 ≥2 次、持续 3 个月可诊断遗尿症。多数为夜间抗利尿激素分泌不足或膀胱容量小，随年龄自愈率高，行为训练与去氨加压素有效。', '白天也尿裤子伴尿痛、发热，或突发遗尿伴多饮多尿（排查糖尿病/尿路感染），尽快就诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('weight-loss', '不明原因消瘦', '全身与代谢', '通用', 'general', '全科医疗科门诊', '半年内体重下降超原体重 5% 而无刻意减重，建议先到全科做系统排查。', 'yellow', '["甲状腺功能亢进","糖尿病（待排查）","消化道肿瘤（需排查）","结核病","焦虑/抑郁"]', '["内分泌科门诊","消化内科门诊","感染科门诊"]', '["记录体重变化曲线与伴随症状（食欲/排便/发热/出汗）。","初筛常包括甲功、血糖、胸片、肿瘤标志物。","50 岁以上消瘦伴大便习惯改变者建议胃肠镜。"]', '无刻意减肥而体重持续下降，需排查“三高消耗”：甲亢（食欲好仍瘦）、糖尿病（多饮多尿）、肿瘤与结核（消耗性）。老年人体重下降尤其要重视消化道肿瘤筛查。', '消瘦伴吞咽困难、黑便/便血、长期低热盗汗或腹部可及包块，尽快专科就诊。')
SELECT 1 FROM DUAL;

INSERT ALL
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('hernia', '疝气 / 腹股沟包块', '外科·普外', '通用', 'giSurg', '胃肠外科门诊', '成人腹股沟疝首选胃肠外科（疝专科）；儿童疝气挂小儿外科。', 'green', '["腹股沟疝","鞘膜积液（儿童）","精索静脉曲张（需区分）"]', '["小儿外科门诊（≤14 岁）","泌尿外科门诊"]', '["鼓包能回纳时平卧轻柔推回，勿暴力按压。","慢性咳嗽、便秘者先治疗，减轻腹压。","确诊后择期手术，避免久拖酿成嵌顿急症。"]', '疝气是腹腔内容物经腹壁薄弱处突出形成，表现为站立、用力、咳嗽时腹股沟鼓包，平卧可回纳。成人疝不会自愈且可能嵌顿，通常建议择期手术修补。', '包块突然变硬、剧痛、推不回去伴恶心呕吐（嵌顿疝/肠绞窄），立即急诊手术。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('gallstone', '胆囊结石 / 胆绞痛', '消化系统', '成人', 'hbSurg', '肝胆胰外科门诊', '无症状胆囊结石可随访观察；反复胆绞痛或伴黄疸者需外科评估手术。', 'green', '["胆囊结石","慢性胆囊炎","急性胆囊炎（待评估）","胆总管结石（需排查）"]', '["消化内科门诊","急诊医学科（急性发作时）"]', '["胆绞痛发作时禁食油腻，疼痛持续超 4-6 小时需急诊。","无症状者每 6-12 个月超声随访。","控制体重、规律早餐可减少新发结石。"]', '胆囊结石是胆汁成分沉淀形成，常于饱餐、油腻后诱发右上腹或剑突下绞痛，可向右肩背放射。多数静止结石无需手术，反复发作或结石 >3cm 者考虑胆囊切除。', '右上腹剧痛伴发热寒战、皮肤眼睛变黄（急性胆管炎），或剧烈腹痛伴血压下降，立即急诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('thyroid-nodule', '甲状腺结节', '内分泌', '通用', 'thyroid', '甲状腺外科门诊', '甲状腺结节首诊甲状腺外科，依超声 TI-RADS 分级决定随访或穿刺。', 'green', '["甲状腺良性结节","结节性甲状腺肿","甲状腺癌（需评估）","桥本甲状腺炎"]', '["内分泌科门诊","普通外科门诊"]', '["携带既往超声报告对比大小变化，建议同一医院复查。","结节 ≥1cm 或分级 ≥4 级者，评估细针穿刺。","伴甲功异常（甲亢/甲减）者同时内分泌随访。"]', '甲状腺结节检出率很高（超声约 20-70%），90% 以上为良性。超声按 TI-RADS 分级评估恶变风险：低级别定期随访，可疑者（≥4 级）行细针穿刺活检。', '结节短期内迅速增大伴声音嘶哑、吞咽困难、呼吸困难或颈部淋巴结肿大，尽快专科就诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('breast-pain', '乳房胀痛 / 乳腺结节', '外科肿瘤', '女性', 'breast', '乳腺外科 / 乳腺专病中心', '周期性胀痛多与激素相关；固定肿块或新发结节需乳腺专科超声评估。', 'green', '["乳腺增生症","乳腺纤维腺瘤","乳腺囊肿","乳腺癌（需排查）"]', '["妇科门诊","甲状腺外科门诊（同源内分泌问题）"]', '["月经结束后 3-7 天自查乳房（视触结合，手法轻柔）。","40 岁以上女性每年一次乳腺超声+钼靶筛查。","控制咖啡因与高脂饮食，穿戴合适内衣。"]', '乳房胀痛随月经周期出现多属乳腺增生，无需过度担心。无痛性、单侧、质硬固定的肿块更需警惕，超声 BI-RADS 分级 ≥4 级需穿刺明确。', '乳头血性溢液、皮肤橘皮样凹陷或肿块迅速增大伴腋窝淋巴结肿大，尽快乳腺专科就诊。')
  INTO triage_entries (entry_id, name, category, population, dept_key, dept_display, dept_note, level_key, diagnoses, alts, tips, science, redline) VALUES ('obesity', '超重 / 肥胖', '全身与代谢', '通用', 'general', '全科医疗科门诊', '减重评估可到全科或内分泌科；医院有体重管理/营养相关门诊可咨询。', 'green', '["单纯性肥胖","代谢综合征","阻塞性睡眠呼吸暂停（重度肥胖时）","多囊卵巢综合征（女性）"]', '["内分泌科门诊","心身医学中心（进食相关问题）"]', '["先做体检评估：血糖、血脂、肝功、尿酸基线。","每月减重 2-4kg 为宜，极速减重易反弹伤身。","重度肥胖合并并发症者咨询减重代谢外科指征。"]', '肥胖（BMI ≥28）或中心性肥胖（腰围男 ≥90cm、女 ≥85cm）显著增加糖尿病、高血压、脂肪肝与关节病风险。科学减重需能量缺口+运动+行为管理三管齐下。', '无直接急诊红线；但肥胖者突发胸痛、气短或单侧腿肿，就医时须主动告知体重史。')
SELECT 1 FROM DUAL;

